"use strict";
/* Lab panels: values, patterns, bedside ties, traps, sources. */
const LABS=[{"id":"fbc","name":"Full blood count","intro":"The FBC asks three bedside questions: is the patient anaemic and why (MCV and reticulocytes point the way), is there a marrow or infection story in the white cells, and are the platelets safe. It confirms pallor, fatigue, bruising and fever stories, but a single count is a snapshot: acute haemorrhage takes 24–72 hours to show as a fall in haemoglobin.","items":[{"k":"Hb","n":"Haemoglobin","ref":"130–170 g/L (men), 120–150 g/L (women) (13–17 and 12–15 g/dL)","meaning":"Oxygen-carrying mass; anaemia is a sign, not a diagnosis, until the MCV and ferritin say why.","high":"Dehydration, smoking, chronic hypoxia (COPD, sleep apnoea), polycythaemia vera (JAK2), testosterone, EPO-secreting tumours.","low":"Blood loss, iron/B12/folate deficiency, chronic disease, CKD, haemolysis, marrow failure, dilution (pregnancy, fluids)."},{"k":"MCV","n":"Mean cell volume","ref":"80–100 fL","meaning":"Sorts anaemia into microcytic, normocytic and macrocytic before any other result is read.","high":"B12/folate deficiency, alcohol, liver disease, hypothyroidism, reticulocytosis, drugs (hydroxycarbamide, azathioprine, methotrexate, zidovudine), myelodysplasia.","low":"Iron deficiency, thalassaemia trait, anaemia of chronic disease (sometimes), sideroblastic anaemia, lead."},{"k":"RDW","n":"Red cell distribution width","ref":"11.5–14.5 %","meaning":"Spread of cell sizes; a high RDW with low MCV favours iron deficiency over thalassaemia trait.","high":"Iron deficiency, mixed deficiency, haemolysis, recent transfusion, myelodysplasia.","low":"Not clinically meaningful."},{"k":"Retics","n":"Reticulocytes","ref":"0.5–2.5 % (25–100 ×10⁹/L)","meaning":"Is the marrow responding? High with anaemia means loss or haemolysis; low means production failure.","high":"Haemolysis, acute bleeding after 3–5 days, response to iron/B12/folate replacement.","low":"Iron/B12/folate deficiency, marrow suppression or infiltration, CKD (low EPO), aplasia."},{"k":"Ferritin","n":"Ferritin","ref":"30–300 µg/L (men), 15–200 (women); <15 diagnostic of iron deficiency, <30 probable","meaning":"Iron stores, but also an acute-phase reactant; 45–100 with raised CRP does not exclude deficiency.","high":"Inflammation, liver disease, malignancy, haemochromatosis, iron overload from transfusion, adult Still's/HLH (very high, >1000s).","low":"Iron deficiency (always; no other cause of a low ferritin)."},{"k":"WCC","n":"White cell count","ref":"4–11 ×10⁹/L","meaning":"Crude; read the differential, never the total alone.","high":"Infection, inflammation, steroids, stress, smoking, leukaemia, post-splenectomy.","low":"Viral infection, sepsis (ominous), drugs, B12/folate deficiency, marrow failure, autoimmune, ethnic benign neutropenia."},{"k":"Neut","n":"Neutrophils","ref":"2.0–7.5 ×10⁹/L (lower in people of African or Middle Eastern ancestry, down to 1.0)","meaning":"Bacterial infection and stress response; left shift and toxic granulation strengthen the case for infection.","high":"Bacterial infection, steroids (demargination within hours, no left shift), trauma, surgery, MI, smoking, G-CSF, CML.","low":"Sepsis, viral infection, chemotherapy, clozapine, carbimazole, co-trimoxazole, autoimmune, marrow infiltration; <0.5 ×10⁹/L with fever is neutropenic sepsis."},{"k":"Lymph","n":"Lymphocytes","ref":"1.0–4.0 ×10⁹/L","meaning":"Viral and chronic immune activity; persistent lymphocytosis in an older adult is CLL until flow cytometry says otherwise.","high":"Viral infection (EBV, CMV, pertussis), CLL, lymphoma, post-splenectomy, stress (transient).","low":"Acute illness and steroids (common and non-specific), HIV, lymphoma, chemotherapy, SLE; counts <1.0 are a poor prognostic marker in sepsis and COVID."},{"k":"Eos","n":"Eosinophils","ref":"<0.5 ×10⁹/L","meaning":"Allergy, parasites and drug reactions; a very high count (>1.5) can itself damage heart and lung.","high":"Asthma/atopy, drugs (DRESS), parasites (strongyloides, schistosoma), Addison's disease, EGPA, lymphoma, hypereosinophilic syndrome.","low":"Steroids, acute stress (eosinopenia is a soft marker of bacterial infection)."},{"k":"Plt","n":"Platelets","ref":"150–400 ×10⁹/L","meaning":"Bleeding risk below 50, spontaneous bleeding below 20; reactive rises are far commoner than clonal ones.","high":"Reactive (infection, inflammation, iron deficiency, bleeding, post-splenectomy, malignancy), essential thrombocythaemia, polycythaemia vera.","low":"ITP, drugs (heparin, quinine, valproate), sepsis/DIC, liver disease and hypersplenism, alcohol, B12 deficiency, HIV, pregnancy (gestational, pre-eclampsia/HELLP), TTP/HUS, marrow failure, pseudothrombocytopenia (EDTA clumping)."}],"patterns":[{"name":"Microcytic anaemia","see":"MCV <80 fL, low ferritin, high RDW","think":"Iron deficiency: GI blood loss until proven otherwise in men and post-menopausal women; menorrhagia in women of reproductive age; coeliac disease at any age. Thalassaemia trait if ferritin normal, RDW normal and red cell count high (Mentzer index MCV/RBC <13).","do":"Ferritin, coeliac serology, urine dipstick; NICE NG12: iron-deficiency anaemia at age 60 and over, or at any age with rectal bleeding, goes on the suspected lower-GI cancer pathway (FIT first, then colonoscopy). Replace iron and check the response at 2–4 weeks (Hb rise of 10–20 g/L)."},{"name":"Macrocytic anaemia","see":"MCV >100 fL","think":"Megaloblastic (B12 or folate deficiency; hypersegmented neutrophils, low reticulocytes, raised LDH and bilirubin from ineffective erythropoiesis) versus non-megaloblastic (alcohol, liver disease, hypothyroidism, myelodysplasia, drugs, reticulocytosis from haemolysis or bleeding).","do":"B12, folate, TFTs, LFTs, GGT, reticulocytes, blood film; if B12 low, check for neurological signs (subacute combined degeneration) and replace B12 before folate. Unexplained macrocytosis with cytopenias in an older adult needs a film and haematology referral for possible myelodysplasia."},{"name":"Normocytic anaemia","see":"MCV 80–100 fL","think":"Anaemia of chronic disease or CKD, acute blood loss (before the MCV has time to fall), mixed iron and B12 deficiency (RDW high), haemolysis (reticulocytes up), early marrow failure.","do":"Reticulocytes split it: high means loss or haemolysis (check bilirubin, LDH, haptoglobin, DAT); low means underproduction (ferritin, B12, folate, CRP, creatinine, TFTs)."},{"name":"Neutrophilia with left shift","see":"Neutrophils >7.5 ×10⁹/L, band forms, toxic granulation, CRP up","think":"Bacterial infection or tissue necrosis; steroids and stress raise neutrophils without a left shift. A count >25 with a normal CRP in a well patient suggests a leukaemoid reaction or CML (check for splenomegaly, basophilia).","do":"Find the source; cultures before antibiotics; recheck in 48 hours. Neutrophilia alone is a weak marker: LR+ for bacterial infection about 1.5–2."},{"name":"Thrombocytosis","see":"Platelets >450 ×10⁹/L","think":"Reactive in over 85%: iron deficiency, infection, inflammation, bleeding, malignancy, post-splenectomy. Persistent unexplained thrombocytosis in adults over 40 carries a cancer risk of about 11% in men and 6% in women.","do":"NICE NG12: a raised platelet count in people aged 40 and over prompts consideration of lung, endometrial, gastric, oesophageal and colorectal cancer alongside other symptoms. Check ferritin and CRP; if persistent and unexplained, JAK2/CALR testing via haematology."},{"name":"Thrombocytopenia","see":"Platelets <150 ×10⁹/L","think":"First exclude EDTA clumping (repeat in citrate, look at the film). Isolated and well: ITP, drugs, alcohol, liver disease, HIV/hepatitis C, pregnancy. Unwell: sepsis/DIC, TTP/HUS (fragments on film and raised LDH are an emergency), HIT (platelets fall >50% 5–10 days after starting heparin, with thrombosis).","do":"Blood film, coagulation screen, LFTs, viral serology; stop candidate drugs. Platelets <20 with bleeding or <10 at all needs same-day haematology; fragments on film means TTP until proven otherwise (do not transfuse platelets, arrange plasma exchange)."},{"name":"Pancytopenia","see":"Hb, WCC and platelets all low","think":"Marrow failure or infiltration (aplastic anaemia, myelodysplasia, leukaemia, lymphoma, myeloma, metastases), B12/folate deficiency, hypersplenism, drugs (chemotherapy, methotrexate, carbimazole), HIV, sepsis, HLH (with very high ferritin and fever).","do":"Film, B12, folate, LDH, reticulocytes, LFTs, viral screen; same-day haematology discussion for marrow examination. Neutrophils <0.5 with fever is neutropenic sepsis: antibiotics within the hour."},{"name":"Polycythaemia","see":"Hb >185 g/L (men) or >165 g/L (women), haematocrit >0.52/0.48","think":"Relative (dehydration, diuretics, alcohol, obesity) versus absolute secondary (hypoxia, smoking, sleep apnoea, EPO-secreting renal or hepatic tumour, testosterone) versus primary (polycythaemia vera: JAK2 V617F in 95%, low EPO, often splenomegaly, pruritus after bathing, thrombosis)."," do":"Repeat when hydrated, SpO2, EPO level, JAK2 mutation; refer haematology for venesection targets if PV."}],"bedside":["Conjunctival pallor: when present LR+ about 4.5 for Hb <90 g/L (conjunctival rim pallor LR+ about 16 but rarely seen); absence of any pallor (conjunctiva, palms, nail beds) LR− about 0.6, so it does not exclude anaemia. Palmar crease pallor LR+ about 7.9.","Koilonychia, angular stomatitis, atrophic glossitis and pica point to iron deficiency; glossitis with peripheral neuropathy or loss of proprioception points to B12.","Petechiae and non-palpable purpura appear with platelets below about 20–30 ×10⁹/L; palpable purpura is vasculitis, not thrombocytopenia.","Splenomegaly with cytopenias suggests hypersplenism, lymphoma, CML or myelofibrosis; splenomegaly with lymphocytosis in a well older adult suggests CLL."],"pitfalls":["Ferritin is an acute-phase reactant: in inflammation, CKD or liver disease a ferritin up to about 100 µg/L can still hide iron deficiency; use transferrin saturation (<20%) and CRP alongside it.","Haemoglobin after acute bleeding is normal for the first few hours; postural pulse rise ≥30/min and tachycardia are the early signs, not the Hb.","Pseudothrombocytopenia from EDTA clumping affects about 1 in 1000 samples; the film shows clumps and a citrate sample gives the true count.","Baseline neutrophil counts of 1.0–1.5 ×10⁹/L are normal in many people of African or Middle Eastern ancestry (Duffy-null phenotype) and need no work-up if the film is normal and there are no infections."],"src":["NICE NG12 Suspected cancer: recognition and referral (2015, updated 2023)","BSG guidelines for the management of iron deficiency anaemia in adults (Snook et al, Gut 2021)","McGee SR. Evidence-Based Physical Diagnosis, 5th ed (pallor LRs; Sheth et al 1997)","BSH guideline on investigation and management of thrombocytopenia; BSH guideline for the diagnosis of B12 and folate deficiency (2024)","Bain BJ. Blood Cells: A Practical Guide, 6th ed"]},{"id":"u-and-e","name":"Urea and electrolytes","intro":"U&E tells you whether the kidneys are filtering, whether the patient is dry, and whether the potassium or sodium is about to cause harm. Creatinine confirms the dehydration or obstruction the history suggested; potassium is read with the ECG, and sodium is read with the volume status and the urine.","items":[{"k":"Na","n":"Sodium","ref":"133–146 mmol/L (mEq/L)","meaning":"A water problem, not a salt problem: sodium reflects the ratio of total body water to solute, governed by ADH and thirst.","high":"Water loss without access to water (elderly, confused, intubated), osmotic diuresis, diabetes insipidus, rarely salt gain (hypertonic saline, bicarbonate).","low":"SIADH (drugs, lung and brain disease, malignancy, pain, nausea), thiazides, hypovolaemia with water replacement, heart failure, cirrhosis, adrenal insufficiency, hypothyroidism, primary polydipsia, low solute intake (beer potomania), pseudohyponatraemia (lipids, paraprotein) and translocational (hyperglycaemia)."},{"k":"K","n":"Potassium","ref":"3.5–5.3 mmol/L (mEq/L)","meaning":"Determines cardiac membrane excitability; the ECG is the bedside readout.","high":"AKI/CKD, ACE inhibitors/ARBs, spironolactone, trimethoprim, NSAIDs, potassium supplements, acidosis, rhabdomyolysis, tumour lysis, haemolysis, Addison's disease, pseudohyperkalaemia (haemolysed or delayed sample, fist clenching, marked leucocytosis or thrombocytosis).","low":"Vomiting, diarrhoea, loop and thiazide diuretics, insulin and beta-agonists (shift), alkalosis, hypomagnesaemia, hyperaldosteronism (with hypertension), refeeding, renal tubular acidosis."},{"k":"Urea","n":"Urea (BUN)","ref":"2.5–7.8 mmol/L (BUN 7–20 mg/dL)","meaning":"Rises with reduced filtration but also with dehydration, GI bleeding, catabolism and high protein intake; falls with liver failure and malnutrition.","high":"Prerenal states, upper GI bleed (absorbed blood protein), steroids, tetracyclines, high protein diet, any AKI/CKD.","low":"Liver failure, malnutrition, pregnancy, SIADH, overhydration."},{"k":"Creat","n":"Creatinine","ref":"59–104 µmol/L men, 45–84 women (0.67–1.18 and 0.51–0.95 mg/dL)","meaning":"Muscle-derived marker of GFR; a rise of 26 µmol/L (0.3 mg/dL) in 48 hours or 1.5× baseline in 7 days defines AKI.","high":"AKI (prerenal, intrinsic, obstructive), CKD, large muscle mass, trimethoprim and cimetidine (block secretion without changing GFR), creatine supplements, cooked meat meal.","low":"Low muscle mass (elderly, cachexia, amputees, neuromuscular disease), pregnancy, liver disease; a normal creatinine in a frail 80 kg-lean-mass patient can hide a GFR under 40."},{"k":"eGFR","n":"Estimated GFR (CKD-EPI 2021, no race term)","ref":"≥90 mL/min/1.73 m² normal; CKD stages G2 60–89, G3a 45–59, G3b 30–44, G4 15–29, G5 <15","meaning":"Valid only in steady state; meaningless during AKI because creatinine lags GFR by a day or more.","high":"Hyperfiltration in early diabetes, pregnancy, low muscle mass (falsely high).","low":"CKD (needs ≥3 months plus albuminuria for diagnosis), or a steady-state snapshot of recovered AKI."},{"k":"HCO3","n":"Bicarbonate","ref":"22–29 mmol/L","meaning":"The metabolic side of acid–base on a venous sample; low bicarbonate with a raised anion gap is the first clue to lactate, ketones or toxins.","high":"Vomiting, diuretics, compensated chronic CO2 retention, mineralocorticoid excess, milk-alkali.","low":"Metabolic acidosis (lactic, keto, renal, diarrhoea, RTA), compensation for chronic hyperventilation."},{"k":"Mg","n":"Magnesium","ref":"0.7–1.0 mmol/L (1.7–2.4 mg/dL)","meaning":"Refractory hypokalaemia and hypocalcaemia will not correct until magnesium is replaced.","high":"Renal failure, magnesium infusions (pre-eclampsia), antacids.","low":"Alcohol, diarrhoea, PPIs (long-term), loop and thiazide diuretics, refeeding, diabetes, cisplatin."},{"k":"UCR","n":"Urea:creatinine ratio","ref":"SI: urea (mmol/L) ÷ creatinine (mmol/L) normally 40–100; >100 prerenal; US: BUN:Cr >20:1 prerenal","meaning":"Urea is reabsorbed when the tubule is avid for water, creatinine is not, so dehydration and GI bleeding raise urea disproportionately.","high":"Prerenal AKI, upper GI bleed, steroids, catabolism.","low":"Rhabdomyolysis (creatinine from muscle), liver disease, malnutrition, dialysis."}],"patterns":[{"name":"Acute kidney injury: KDIGO staging","see":"Stage 1: creatinine 1.5–1.9× baseline or rise ≥26.5 µmol/L (0.3 mg/dL) within 48 h, or urine output <0.5 mL/kg/h for 6–12 h. Stage 2: 2.0–2.9× baseline or urine <0.5 mL/kg/h for ≥12 h. Stage 3: ≥3× baseline, or creatinine ≥353.6 µmol/L (4.0 mg/dL), or renal replacement started, or urine <0.3 mL/kg/h for ≥24 h or anuria ≥12 h.","think":"Prerenal (hypovolaemia, sepsis, heart failure, NSAIDs plus ACE inhibitor plus diuretic: the triple whammy) in about 70%; obstruction in 5–10% (older men, single kidney, pelvic malignancy, anticholinergics); intrinsic (ATN after prolonged prerenal insult or contrast, glomerulonephritis with blood and protein on dipstick, interstitial nephritis with rash, fever, eosinophilia, drugs such as PPIs and antibiotics).","do":"Urine dipstick in every AKI (blood plus protein means glomerular disease until proven otherwise), bladder scan or ultrasound within 24 h if obstruction possible or cause unclear, stop nephrotoxins (NICE NG148), fluid balance and daily U&E, hold metformin and reduce renally cleared drugs. Refer nephrology for stage 3, unclear cause, glomerular picture or no recovery."},{"name":"Hyperkalaemia with ECG changes","see":"K ≥6.5 mmol/L (severe) or any K >5.5 with ECG changes: peaked T waves (earliest, K >5.5–6.5), PR prolongation and flattened P (6.5–7.5), widened QRS, then sine wave and asystole or VF (>8). UK Kidney Association grades mild 5.5–5.9, moderate 6.0–6.4, severe ≥6.5.","think":"Pseudohyperkalaemia first if the patient is well with a normal ECG (haemolysed sample, fist clenching, thrombocytosis >500, leucocytosis >50, sample left standing). Then AKI/CKD plus ACE inhibitor, spironolactone, trimethoprim; tumour lysis, rhabdomyolysis, Addison's (with low Na, high urea, hypotension), acidosis.","do":"12-lead ECG and monitor immediately. ECG changes or K ≥6.5: 30 mL 10% calcium gluconate IV over 5–10 min (repeat until QRS narrows), 10 units soluble insulin in 25 g glucose, nebulised salbutamol 10–20 mg, then remove potassium (stop drugs, treat cause, consider sodium zirconium cyclosilicate or patiromer, dialysis if refractory). Recheck K at 1 h and watch for hypoglycaemia for 6 h."},{"name":"Hypokalaemia","see":"K <3.5; severe <2.5 or symptomatic. ECG: flattened T, prominent U, ST depression, prolonged QU interval, ventricular ectopy and torsades (especially with digoxin or long QT drugs).","think":"GI loss (vomiting with alkalosis, diarrhoea with acidosis), diuretics, intracellular shift (insulin, salbutamol, refeeding, alkalosis, thyrotoxic periodic paralysis), hypomagnesaemia, renal loss (hyperaldosteronism if hypertensive with alkalosis, Bartter/Gitelman if normotensive, RTA, amphotericin).","do":"Check magnesium and replace first if low. Oral potassium if >2.5 and asymptomatic; IV at no more than 10 mmol/h peripherally (20 mmol/h on a monitor centrally) if <2.5, symptomatic or ECG changes. Urine potassium and spot K:creatinine ratio (>1.5 mmol/mmol means renal loss) if the cause is unclear."},{"name":"Hyponatraemia: the four questions","see":"Na <135; severe <125 or symptomatic (confusion, seizures, vomiting). Ask in order: (1) serum osmolality (<275 mOsm/kg confirms true hypotonic hyponatraemia; normal or high means pseudohyponatraemia or glucose/mannitol); (2) urine osmolality (<100 mOsm/kg means the kidney is diluting appropriately: polydipsia, low solute, beer potomania; >100 means ADH is acting); (3) urine sodium (<30 mmol/L: low effective volume from vomiting, diarrhoea, heart failure, cirrhosis; >30: SIADH, diuretics, adrenal insufficiency, renal salt wasting); (4) volume status at the bedside.","think":"SIADH is a diagnosis of exclusion: euvolaemic, urine osmolality >100, urine Na >30, normal thyroid and cortisol, no diuretics. Thiazides and SSRIs are the commonest drug causes in older adults. Correct glucose: add 2.4 mmol/L sodium for every 5.6 mmol/L (100 mg/dL) glucose above 5.6.","do":"Severe symptoms: 150 mL 3% hypertonic saline over 20 min, repeat up to twice, aiming for a 5 mmol/L rise, then stop. Otherwise treat the cause: fluid restriction 1 L/day for SIADH, isotonic saline for hypovolaemia, stop the offending drug. Limit correction to 8–10 mmol/L in the first 24 h (osmotic demyelination risk, especially with alcohol, malnutrition, hypokalaemia, liver disease); recheck sodium every 4–6 h during active treatment. Check TSH and 9 am cortisol in every euvolaemic case."},{"name":"Hypernatraemia","see":"Na >146; severe >160","think":"Almost always water deficit in someone who cannot drink: frail elderly, dementia, sedated, ventilated. Osmotic diuresis (hyperglycaemia, mannitol), diabetes insipidus (urine osmolality inappropriately low, <300, with polyuria; cranial after pituitary surgery or head injury, nephrogenic with lithium), excess hypertonic fluids.","do":"Calculate the free water deficit (0.6 × weight × (Na/140 − 1) in litres), replace enterally where possible, correct no faster than 10–12 mmol/L per 24 h if chronic (>48 h). Measure paired serum and urine osmolality before giving fluids if DI is suspected."},{"name":"Prerenal versus intrinsic AKI","see":"Prerenal: urea rises more than creatinine (urea:creatinine >100 in SI, BUN:Cr >20), urine Na <20 mmol/L, FENa <1%, bland dipstick, concentrated urine, creatinine falls within 24–48 h of fluid. ATN: urea and creatinine rise together, urine Na >40, FENa >2%, muddy brown granular casts, no response to fluid.","think":"FENa is unreliable on diuretics (use fractional excretion of urea <35% for prerenal) and in contrast nephropathy, rhabdomyolysis and glomerulonephritis where it is low despite intrinsic injury.","do":"Fluid challenge 500 mL crystalloid over 15 min and reassess; if no response by 24–48 h or the dipstick is active, think intrinsic disease and image. Bladder scan first in any oliguric patient."},{"name":"Chronic kidney disease staging and referral","see":"eGFR <60 or ACR ≥3 mg/mmol persisting 3 months. G stages as above; A1 <3, A2 3–30, A3 >30 mg/mmol.","think":"Diabetes and hypertension cause most; small kidneys on ultrasound, anaemia, hyperphosphataemia and hypocalcaemia favour chronic over acute. The ACR, not just the eGFR, drives cardiovascular and renal risk.","do":"NICE NG203: refer nephrology if eGFR <30, ACR ≥70 mg/mmol, ACR ≥30 with haematuria, sustained fall in eGFR ≥25% with stage change or ≥15 mL/min/1.73 m² per year, suspected rare cause, or uncontrolled hypertension on four agents. SGLT2 inhibitor and ACE inhibitor/ARB for albuminuric CKD."}],"bedside":["Dry axilla LR+ about 2.8 for hypovolaemia; postural pulse rise ≥30/min or severe postural dizziness LR+ about 48 for large acute blood loss but poor for moderate; capillary refill >2 s LR+ about 6 in vomiting or diarrhoea. None reliably predicts the creatinine; U&E confirms the clinical impression.","Suprapubic dullness or a palpable bladder in an oliguric older man means obstruction until the bladder scan says otherwise.","Muscle weakness, ileus and absent reflexes go with severe hypokalaemia; cramps and paraesthesiae with hypomagnesaemia. Hyperkalaemia usually has no signs before the ECG changes.","Confusion, gait disturbance and falls in an older adult on a thiazide are the usual presentation of hyponatraemia; look at the drug chart before the sodium."],"pitfalls":["Creatinine underestimates renal impairment in the frail, sarcopenic and elderly; a creatinine of 100 µmol/L in a 45 kg 85-year-old woman may represent an eGFR under 40 and a drug-dosing problem.","eGFR is invalid in AKI, pregnancy, amputees, extremes of muscle mass and within 48 h of a large change in creatinine; use measured urine output and creatinine trend instead.","Potassium rises about 0.5 mmol/L for every 0.1 fall in pH, and a haemolysed or delayed sample can add 1–2 mmol/L; repeat with a free-flowing sample before treating a surprising result in a well patient.","Trimethoprim and cimetidine raise creatinine by about 15–30% by blocking tubular secretion without reducing GFR; trimethoprim also raises potassium (amiloride-like effect), dangerous with ACE inhibitors or spironolactone."],"src":["KDIGO Clinical Practice Guideline for Acute Kidney Injury (2012) and KDIGO 2024 CKD guideline","NICE NG148 Acute kidney injury: prevention, detection and management (2019)","NICE NG203 Chronic kidney disease: assessment and management (2021)","UK Kidney Association clinical practice guideline: treatment of acute hyperkalaemia in adults (2023)","Spasovski G et al. ESE/ERA-EDTA/ESICM guideline on diagnosis and treatment of hyponatraemia (2014); NICE NG29 Intravenous fluid therapy in adults","McGee SR. Evidence-Based Physical Diagnosis, 5th ed (hypovolaemia signs)"]},{"id":"lfts","name":"Liver function tests","intro":"LFTs do two different jobs: the enzymes (ALT, AST, ALP, GGT) tell you where the injury is, hepatocellular or cholestatic, and the synthetic markers (albumin, INR, bilirubin) tell you how much liver is left. The bedside question is usually whether the jaundice, pain or confusion comes from a blocked duct, a poisoned hepatocyte or a failing organ.","items":[{"k":"ALT","n":"Alanine aminotransferase","ref":"Lab range typically up to 40 U/L; true healthy upper limit about 30 U/L (men) and 19–25 (women)","meaning":"Hepatocyte-specific enzyme; the marker of hepatocellular injury.","high":"Fatty liver (commonest), viral hepatitis, alcohol, drugs (paracetamol, statins, antibiotics, anti-TB), autoimmune hepatitis, haemochromatosis, coeliac disease, muscle injury (small rise); >1000 U/L means ischaemic, viral, paracetamol, autoimmune hepatitis or acute duct obstruction (briefly).","low":"Not significant (seen in CKD, B6 deficiency, elderly)."},{"k":"AST","n":"Aspartate aminotransferase","ref":"10–40 U/L","meaning":"Also in muscle, heart and red cells; useful mainly in the AST:ALT ratio.","high":"Same as ALT plus myositis, rhabdomyolysis, MI, haemolysis; AST:ALT >2 suggests alcohol, >1 suggests cirrhosis of any cause.","low":"Not significant."},{"k":"ALP","n":"Alkaline phosphatase","ref":"30–130 U/L (higher in pregnancy and adolescence)","meaning":"Cholestasis or bone turnover; GGT decides which.","high":"Biliary obstruction, cholestatic drugs (co-amoxiclav, flucloxacillin), PBC, PSC, infiltration (metastases, lymphoma, TB, amyloid), bone (Paget's, metastases, fracture, osteomalacia, hyperparathyroidism), pregnancy (placental), growth.","low":"Hypophosphatasia, hypothyroidism, zinc deficiency, severe malnutrition (rare)."},{"k":"GGT","n":"Gamma-glutamyl transferase","ref":"<55 U/L (men), <38 (women)","meaning":"Confirms a raised ALP is hepatic; alone, it is too non-specific to act on.","high":"Alcohol, fatty liver, enzyme-inducing drugs (phenytoin, carbamazepine, rifampicin), any cholestasis, heart failure, pancreatic disease.","low":"Not significant."},{"k":"Bili","n":"Bilirubin (total)","ref":"<21 µmol/L (<1.2 mg/dL)","meaning":"Clinical jaundice appears above about 40–50 µmol/L (2.5–3 mg/dL), first in the sclerae. Split into conjugated and unconjugated when isolated.","high":"Unconjugated: haemolysis, Gilbert's (fasting, illness), ineffective erythropoiesis; conjugated: hepatocellular disease, cholestasis, obstruction, drugs, sepsis.","low":"Not significant."},{"k":"Alb","n":"Albumin","ref":"35–50 g/L (3.5–5.0 g/dL)","meaning":"Synthetic function over weeks (half-life 20 days); also a negative acute-phase reactant, so it falls in any serious illness.","high":"Dehydration.","low":"Chronic liver disease, nephrotic syndrome, protein-losing enteropathy, malnutrition, sepsis and inflammation, overhydration, pregnancy."},{"k":"INR","n":"INR / prothrombin time","ref":"INR 0.8–1.2; PT 11–14 s","meaning":"Synthetic function over hours (factor VII half-life 6 h): the best acute marker of liver failure and the key prognostic number in paracetamol poisoning.","high":"Acute liver failure, cirrhosis, vitamin K deficiency (prolonged cholestasis, malabsorption, antibiotics), warfarin, DIC.","low":"Not significant."}],"patterns":[{"name":"Hepatocellular versus cholestatic: the R ratio","see":"R = (ALT ÷ ALT upper limit) ÷ (ALP ÷ ALP upper limit). R ≥5 hepatocellular, R ≤2 cholestatic, 2–5 mixed.","think":"Hepatocellular: viral hepatitis (A, B, C, E; EBV, CMV), drugs and paracetamol, alcohol, autoimmune hepatitis, ischaemia, Wilson's in the young, Budd-Chiari. Cholestatic: stones, malignancy (pancreas, cholangiocarcinoma), drug cholestasis (co-amoxiclav can present weeks after the course), PBC (anti-mitochondrial antibody), PSC (ulcerative colitis), sepsis, infiltration.","do":"Cholestatic pattern: ultrasound within days (dilated ducts mean obstruction, go to MRCP or ERCP); undilated ducts, check AMA, ANA, IgG, drug history. Hepatocellular: hepatitis serology, paracetamol level, autoimmune screen, ferritin, caeruloplasmin if under 40, ultrasound. BSG 2017: a full non-invasive liver screen on the first abnormal result rather than repeating."},{"name":"ALT in the thousands","see":"ALT or AST >1000 U/L","think":"Ischaemic hepatitis (shock, heart failure, hypoxia; AST peaks fast and falls within days, LDH very high), paracetamol (peak 48–72 h), acute viral hepatitis, autoimmune hepatitis, acute biliary obstruction (transient, with pain), Budd-Chiari, HSV, heat stroke, cocaine. Alcohol alone rarely exceeds 300–500.","do":"Paracetamol level and INR immediately; INR, bilirubin, glucose, lactate, pH and encephalopathy grade determine whether this is acute liver failure. King's College criteria for paracetamol: arterial pH <7.3 after resuscitation, or INR >6.5 plus creatinine >300 µmol/L plus grade 3–4 encephalopathy; discuss with a liver unit early."},{"name":"Alcohol-related liver disease","see":"AST:ALT >2 with both usually <300 U/L, GGT high, MCV >100, low platelets, raised IgA; bilirubin >50 with fever and neutrophilia suggests alcoholic hepatitis.","think":"Alcoholic hepatitis (Maddrey discriminant function ≥32 or Glasgow score ≥9 identifies severe disease), decompensated cirrhosis, pancreatitis, Wernicke's. The ratio is also >1 in cirrhosis of any cause.","do":"Full liver screen, ultrasound, AUDIT, thiamine before glucose, pabrinex, monitor for withdrawal; NICE CG100 for severe alcoholic hepatitis. FIB-4 and transient elastography for fibrosis staging in those not acutely unwell."},{"name":"Isolated raised ALP","see":"ALP high, ALT and bilirubin normal","think":"GGT normal: bone (Paget's, metastases, osteomalacia, healing fracture, hyperparathyroidism), pregnancy third trimester, growth. GGT raised: early cholestasis, infiltration (metastases, lymphoma, sarcoid, TB, amyloid), PBC, PSC, drug cholestasis.","do":"GGT, calcium, phosphate, vitamin D, PTH, bone-specific ALP or isoenzymes if unclear; ultrasound and AMA if hepatic. Persistent unexplained hepatic ALP needs imaging for infiltration."},{"name":"Isolated raised bilirubin","see":"Bilirubin raised with normal enzymes","think":"Unconjugated (>80% of total): Gilbert's syndrome (3–7% of the population, bilirubin <80 µmol/L, rises with fasting, illness and exercise, normal FBC and reticulocytes) or haemolysis (reticulocytes up, LDH up, haptoglobin down, blood film). Conjugated: Dubin-Johnson, Rotor, early sepsis, drug.","do":"Split bilirubin, FBC, reticulocytes, LDH, haptoglobin, blood film. Gilbert's needs reassurance and no follow-up once haemolysis is excluded."},{"name":"Failing synthetic function","see":"INR >1.5 not on anticoagulants, albumin <30, bilirubin rising, with or without low glucose, low urea, encephalopathy, ascites","think":"Acute liver failure (INR >1.5 plus encephalopathy within 26 weeks of onset without prior liver disease) or decompensated cirrhosis; precipitants of decompensation are infection (SBP), GI bleeding, drugs, alcohol, constipation, dehydration, hepatocellular carcinoma, portal vein thrombosis.","do":"Glucose hourly if INR >3, lactate, ammonia, blood cultures, ascitic tap (neutrophils ≥250/mm³ means SBP), paracetamol level; Child-Pugh and MELD; early liver unit discussion for acute liver failure. Vitamin K 10 mg IV once distinguishes deficiency (INR corrects within 24 h) from true synthetic failure (it does not)."},{"name":"Fatty liver with persistent mild ALT rise","see":"ALT 1–3× upper limit, R ratio hepatocellular, obesity or diabetes, bright liver on ultrasound, viral and autoimmune screen negative","think":"MASLD (metabolic dysfunction-associated steatotic liver disease), the commonest cause of abnormal LFTs in primary care; the question is fibrosis, not the ALT (which is normal in many with cirrhosis).","do":"FIB-4 (age, AST, ALT, platelets): <1.3 low risk, >2.67 high risk (use 2.0 as the lower cut-off over 65); NICE NG49 ELF test ≥10.51 or transient elastography for intermediate or high scores; manage weight, diabetes and alcohol; refer if advanced fibrosis."}],"bedside":["Scleral icterus is visible above about 40–50 µmol/L bilirubin in daylight; the palate and sublingual mucosa are the next places to look in darker skin.","Signs of chronic liver disease (spider naevi >5, palmar erythema, gynaecomastia, Dupuytren's, parotid swelling, leuconychia) tell you the problem is chronic; none correlates with the degree of enzyme rise. Spider naevi and palmar erythema are weak individually but their combination with firm liver edge and splenomegaly makes cirrhosis likely.","Asterixis (flap), constructional apraxia and fetor are the bedside grading of hepatic encephalopathy; ammonia adds little once encephalopathy is clinically present.","Shifting dullness LR+ about 2 and fluid thrill LR+ about 6 for ascites; a low albumin with ascites suggests cirrhosis or nephrotic syndrome and the serum-ascites albumin gradient (≥11 g/L) confirms portal hypertension."],"pitfalls":["ALT is normal in a substantial proportion of patients with cirrhosis and in advanced MASLD; normal enzymes do not exclude serious liver disease. Platelets <150 and AST:ALT >1 are better clues.","Albumin and INR are not liver-specific: sepsis, nephrotic syndrome and malnutrition lower albumin; vitamin K deficiency, warfarin and DIC raise the INR. Give vitamin K before calling an INR hepatic.","Drug-induced cholestasis (co-amoxiclav, flucloxacillin, anabolic steroids) can appear 1–6 weeks after the drug was stopped; take a three-month drug and supplement history.","Lab reference ranges for ALT are set from populations that include people with fatty liver; an ALT of 35 U/L in a slim woman is abnormal by the healthy upper limit of 19–25."],"src":["Newsome PN et al. Guidelines on the management of abnormal liver blood tests. BSG, Gut 2018","NICE NG49 Non-alcoholic fatty liver disease: assessment and management (2016); NICE CG100 Alcohol-use disorders (2010)","EASL Clinical Practice Guidelines on acute (fulminant) liver failure (2017) and on drug-induced liver injury (2019)","Kwo PY et al. ACG Clinical Guideline: evaluation of abnormal liver chemistries. Am J Gastroenterol 2017","McGee SR. Evidence-Based Physical Diagnosis, 5th ed (jaundice, ascites, chronic liver disease signs)"]},{"id":"inflammatory","name":"Inflammatory markers","intro":"CRP, ESR and procalcitonin answer one question, is there systemic inflammation, and only partly a second, is it bacterial. They confirm the fever, the hot joint or the temporal headache you already suspected, and their trend over 48 hours is worth more than any single value. None of them makes or excludes a diagnosis on its own.","items":[{"k":"CRP","n":"C-reactive protein","ref":"<5 mg/L (some labs <10)","meaning":"Hepatic acute-phase protein driven by IL-6; rises within 6–8 h, peaks at 36–50 h, half-life 19 h, so it tracks the course of inflammation in days.","high":"Bacterial infection (often >100), tissue necrosis, surgery and trauma, active inflammatory disease (RA, Crohn's, vasculitis, gout), malignancy (lymphoma, renal), obesity (mild, 3–10).","low":"Normal; note CRP stays low in active SLE, scleroderma and ulcerative colitis, in IL-6 blockade (tocilizumab), and in the first 6 hours of any insult."},{"k":"ESR","n":"Erythrocyte sedimentation rate","ref":"Upper limit about age ÷ 2 (men) and (age + 10) ÷ 2 (women) mm/h","meaning":"Indirect measure of fibrinogen and immunoglobulins; rises and falls over weeks, so it lags CRP.","high":"Infection, inflammation, myeloma and paraproteins (ESR >100 with normal CRP), GCA/PMR, anaemia, pregnancy, old age, CKD, malignancy.","low":"Polycythaemia, sickle cell disease, hypofibrinogenaemia (DIC, liver failure), heart failure, spherocytosis."},{"k":"PCT","n":"Procalcitonin","ref":"<0.1 ng/mL (µg/L) normal; 0.1–0.25 bacterial infection unlikely; 0.25–0.5 possible; ≥0.5 likely; >2 systemic bacterial infection or septic shock","meaning":"Rises within 2–4 h of bacterial endotoxin exposure and is suppressed by interferon in viral infection; more specific for bacterial sepsis than CRP but not for localised infection.","high":"Bacterial sepsis, bacterial pneumonia, pyelonephritis, meningitis; also severe trauma, surgery, burns, cardiogenic shock, medullary thyroid cancer, and the first 48 h of life.","low":"Viral infection, localised infection (abscess, empyema, endocarditis can be low), early in the course (<6 h), antibiotics already given."},{"k":"Ferr","n":"Ferritin as acute-phase reactant","ref":"30–300 µg/L; >1000 is unusual outside iron overload, liver disease, malignancy and hyperinflammation","meaning":"A very high ferritin (>5000 µg/L, or >10 000) with fever and cytopenias suggests adult-onset Still's disease or haemophagocytic lymphohistiocytosis.","high":"Inflammation, liver injury, malignancy, haemochromatosis, transfusion, HLH/MAS, Still's.","low":"Iron deficiency."},{"k":"WCC","n":"White cells with inflammatory markers","ref":"Neutrophils 2–7.5 ×10⁹/L","meaning":"Neutrophilia with raised CRP supports bacterial infection; lymphopenia and neutrophilia together (NLR >10) mark severity.","high":"See FBC.","low":"See FBC."}],"patterns":[{"name":"Suspected bacterial infection: can CRP decide?","see":"CRP <20 mg/L versus >100 mg/L in a patient with respiratory symptoms","think":"NICE CG191 for lower respiratory tract infection in primary care without a clinical diagnosis of pneumonia: CRP <20, do not routinely offer antibiotics; 20–100, consider a delayed prescription; >100, offer antibiotics. Across infections, CRP >100 roughly doubles the odds of bacterial over viral cause (LR+ about 2–3) and CRP <10 lowers it (LR− about 0.2–0.3), but overlap is wide; a well-looking patient with CRP 150 may have influenza and a toxic one with CRP 15 may be 4 hours into pneumococcal sepsis.","do":"Use CRP to support a decision, not to make it; always combine with examination (focal signs, respiratory rate, oxygen saturation) and the time since onset. Repeat at 48 h: a fall of 25–50% supports response; a CRP still rising on day 3 of antibiotics means wrong drug, undrained collection or wrong diagnosis."},{"name":"Giant cell arteritis","see":"Age ≥50, new headache, scalp tenderness, jaw claudication, visual symptoms, PMR; ESR ≥50 mm/h (ACR criterion) and CRP raised, platelets often high, mild normocytic anaemia, ALP mildly raised in 20–30%","think":"GCA is a clinical diagnosis confirmed by ultrasound (halo sign) or biopsy; markers support it. Both ESR and CRP are normal in about 1–4% of biopsy-proven cases; CRP alone is normal in about 4%, ESR alone in about 10%. Jaw claudication LR+ about 4, temporal artery beading LR+ about 4.6, absent temporal pulse LR+ about 2.7.","do":"Do not wait for results if vision is threatened: start prednisolone 40–60 mg (IV methylprednisolone for visual loss) and refer same day for temporal artery ultrasound or biopsy within 1–2 weeks (biopsy sensitivity falls after 2 weeks of steroids). Monitor ESR/CRP with symptoms during tapering; on tocilizumab CRP is suppressed and cannot be used to detect relapse."},{"name":"Septic arthritis","see":"Hot swollen joint; CRP and ESR usually raised, WCC often raised, fever in only about 50%","think":"Normal inflammatory markers do not exclude septic arthritis (CRP normal in up to 10–15% of cases, ESR normal in about 10%, WCC normal in over 40%), and raised markers do not distinguish it from gout or pseudogout. Risk factors: prosthetic joint, RA, diabetes, age >80, recent joint injection, skin infection, IV drug use, immunosuppression.","do":"Aspirate before antibiotics (BSR/BOA hot swollen joint guideline): Gram stain, culture, crystals, cell count; blood cultures; synovial WCC >50 000 raises the likelihood substantially (see synovial fluid panel). Treat as septic until the culture is back if the clinical picture fits, regardless of CRP."},{"name":"Discordant ESR and CRP","see":"ESR very high with CRP normal or mildly raised; or CRP high with ESR normal","think":"ESR high, CRP low: myeloma and other paraproteinaemias, SLE, anaemia, pregnancy, CKD, old age, polycythaemia excluded. CRP high, ESR normal: early infection (first 24–48 h), ESR lowered by polycythaemia, sickle cell, low fibrinogen, or microcytosis. In SLE a raised CRP suggests infection or serositis rather than a flare.","do":"ESR >100 mm/h: serum protein electrophoresis and free light chains, calcium, creatinine, FBC (myeloma); consider GCA, TB, abscess, endocarditis, metastatic cancer, vasculitis; NICE NG12 lists plasma viscosity or ESR in the myeloma assessment for over-60s with hypercalcaemia or leucopenia."},{"name":"Procalcitonin to stop antibiotics","see":"PCT <0.25 ng/mL, or a fall ≥80% from the peak, in a patient improving on antibiotics for respiratory infection or sepsis","think":"Procalcitonin-guided discontinuation safely shortens antibiotic courses in RCTs (ProACT, SAPS, PRORATA); its value for starting antibiotics is weaker, and NICE DG18 (2015) did not recommend routine use, with the Cochrane evidence supporting use in de-escalation. It does not help in localised, contained infection or in immunosuppressed patients, and surgery, trauma, cardiogenic shock and renal failure raise it without bacteria.","do":"Use it as one input to a stop decision at 48–72 h, with clinical response and CRP trend; never withhold antibiotics in a septic patient because PCT is low early."},{"name":"Fever with no source and modest markers","see":"CRP 20–60, ESR moderately raised, WCC normal, no focus on examination","think":"Viral infection, early bacterial infection, endocarditis (listen again for a murmur, look at nails and fundi, send three blood culture sets), abscess (dental, liver, pelvic), TB, drug fever, thromboembolism, malignancy (lymphoma, renal), adult Still's (ferritin, rash), vasculitis, thyroiditis.","do":"Repeat examination and markers at 48 h; the trajectory often declares itself. Fever persisting >3 weeks with markers raised and basic work-up negative is pyrexia of unknown origin: cultures ×3, HIV, echo, CT chest-abdomen-pelvis, consider PET-CT."}],"bedside":["Respiratory rate >22, new confusion and systolic BP ≤100 (qSOFA) or a NEWS2 ≥5 are bedside sepsis flags that outweigh any CRP value; a normal CRP in the first 6 hours of sepsis is expected.","Temporal artery tenderness, beading or reduced pulsation (LR+ about 2.7–4.6) with a raised ESR makes GCA likely; a normal artery does not exclude it.","A hot, swollen, immobile joint with fever has septic arthritis in about 10–20% of cases presenting to the ED; inflammatory markers do not change the need to aspirate.","Splinter haemorrhages, new regurgitant murmur and microscopic haematuria with raised CRP in a febrile patient should prompt blood cultures before antibiotics (endocarditis)."],"pitfalls":["CRP needs 6–12 hours to rise: a normal CRP at the door in a patient with a short history is uninformative; repeat at 12–24 h if the examination worries you.","Steroids, tocilizumab and other IL-6 or JAK inhibitors blunt or abolish the CRP response; an infection can be severe with a CRP under 10 on these drugs.","Post-operative CRP peaks on day 2–3 (often 100–200 after major surgery) and halves every 2–3 days; a rise after day 4 or a failure to fall suggests infection, anastomotic leak or VTE.","ESR depends on red cell number and shape: anaemia raises it, polycythaemia and sickle cell lower it, and a sample left over 4 hours gives a false low."],"src":["NICE CG191 Pneumonia in adults: diagnosis and management (2014, updated 2023); NICE NG138 Pneumonia (community-acquired): antimicrobial prescribing","NICE DG18 Procalcitonin testing for diagnosing and monitoring sepsis (2015); Schuetz P et al. Cochrane Database Syst Rev 2017 (procalcitonin to initiate or discontinue antibiotics)","Mackie SL et al. BSR guideline on diagnosis and treatment of giant cell arteritis (2020); Kermani TA et al. Utility of ESR and CRP for the diagnosis of GCA. Semin Arthritis Rheum 2012","Coakley G et al. BSR/BHPR/BOA/RCGP guideline for the management of the hot swollen joint in adults (2006); Margaretten ME et al. Does this adult patient have septic arthritis? JAMA 2007","NICE NG51 Sepsis: recognition, diagnosis and early management (2016, updated 2024); Pepys MB, Hirschfield GM. C-reactive protein: a critical update. J Clin Invest 2003"]},{"id":"troponin","name":"Troponin","intro":"High-sensitivity troponin confirms or refutes the myocardial infarction that the chest pain, the ECG and the risk factors suggested, and it does it within an hour of arrival when paired with a second sample. But troponin reports myocardial injury, not its cause: a raised value in a patient whose story is sepsis, PE or tachyarrhythmia is still injury, just not a type 1 infarction.","items":[{"k":"hsTnT","n":"High-sensitivity troponin T (Roche Elecsys)","ref":"99th percentile 14 ng/L; ESC 0/1 h cut-offs: rule-out very low <5 ng/L at 0 h (if pain onset >3 h), or 0 h <12 and 1 h change <3; rule-in 0 h ≥52 or 1 h change ≥5; otherwise observe and resample at 3 h","meaning":"Cardiomyocyte structural protein released with necrosis; the hs assays detect the normal turnover in most healthy people, so interpretation is about change over time, not just a threshold.","high":"Type 1 MI (plaque rupture), type 2 MI (supply-demand mismatch: tachyarrhythmia, hypotension, anaemia, hypoxia, severe hypertension, spasm, SCAD), myocarditis, Takotsubo, PE, aortic dissection, heart failure, cardiac contusion, cardioversion, ablation, sepsis, CKD, stroke and SAH, strenuous endurance exercise, rhabdomyolysis and skeletal myopathy (hs-TnT in particular), chemotherapy.","low":"Values below the limit of detection at ≥3 h from symptom onset carry a negative predictive value for MI above 99%."},{"k":"hsTnI","n":"High-sensitivity troponin I (assay-specific)","ref":"Abbott Architect: 99th percentile 26 ng/L (sex-specific 16 women, 34 men); ESC 0/1 h rule-out <4 ng/L at 0 h, or <5 with 1 h change <2; rule-in ≥64 or change ≥6. Other assays (Siemens, Beckman) have their own tables; use the local pathway.","meaning":"Same release kinetics, different numbers; never transfer cut-offs between assays or between hospitals.","high":"As for troponin T; troponin I is less affected by skeletal muscle disease.","low":"As above."},{"k":"delta","n":"Absolute change (delta) between samples","ref":"Assay-specific: for hs-TnT a 1 h change ≥5 ng/L or 2 h change ≥10 is rule-in; for 0/3 h pathways a change >50% of the 99th percentile when baseline is below it, or >20% when baseline is above it","meaning":"A rising-falling pattern distinguishes acute injury from chronic elevation (CKD, heart failure, LVH, stable cardiomyopathy); chronic elevation is flat.","high":"Acute injury of any cause, including type 2 MI and myocarditis.","low":"Flat raised values: chronic myocardial injury; still carry long-term risk."},{"k":"99th","n":"The 99th percentile upper reference limit","ref":"Assay-specific; sex-specific values are recommended by the ESC (lower in women)","meaning":"The threshold for myocardial injury under the Fourth Universal Definition; MI requires injury plus clinical evidence of ischaemia (symptoms, ECG, imaging, angiography).","high":"Values above it with a rise or fall define acute myocardial injury.","low":"Values below it do not exclude unstable angina, which by definition has no troponin rise."}],"patterns":[{"name":"ESC 0/1 h rule-out","see":"Very low troponin on arrival (hs-TnT <5 ng/L, hs-TnI Architect <4) with symptom onset >3 h ago; or low troponin (hs-TnT <12, hs-TnI <5) with a 1 h change below the assay delta (hs-TnT <3, hs-TnI <2), and no ongoing pain or ischaemic ECG changes","think":"Negative predictive value for 30-day MI or death about 99.5%; about 60–70% of chest pain presentations rule out this way. Early presenters (<3 h) need the second sample even if the first is very low. The 0/2 h algorithm is an alternative with slightly different cut-offs; 0/3 h remains acceptable where 1 h sampling is impractical.","do":"Discharge from the MI pathway with a plan: consider outpatient functional or CT coronary testing if the story was typical (HEART or EDACS score helps); unstable angina is not excluded by troponin, so admit a patient with ongoing or crescendo pain at rest despite a negative pathway."},{"name":"ESC 0/1 h rule-in","see":"hs-TnT ≥52 ng/L on arrival or 1 h rise ≥5; hs-TnI Architect ≥64 or rise ≥6","think":"Positive predictive value for MI about 70–75%: the remaining quarter are type 2 MI, myocarditis, Takotsubo, PE, dissection and other injury. The ECG and the story decide: ST elevation goes to the cath lab regardless of troponin; a young febrile patient with pericarditic pain and diffuse ST elevation is myocarditis until echo and MRI say otherwise.","do":"Aspirin, anticoagulation and invasive strategy within 24 h for NSTEMI with high-risk features (GRACE >140, dynamic ST changes, haemodynamic instability goes immediately); echo for wall-motion and alternative diagnoses; exclude dissection before anticoagulating if the pain is tearing or pulses asymmetric."},{"name":"Observe zone","see":"Neither rule-out nor rule-in: hs-TnT 12–52 with a small change, or very low on arrival but presentation <3 h, or 1 h sample unavailable","think":"About 20–25% of patients; MI prevalence in this group is around 15–20%, and most of the rest have chronic injury or type 2 MI. CKD, heart failure and age shift baseline values upwards.","do":"Third sample at 3 h from arrival (or 3 h from the first sample), ECG repeated, echo if available; compare to previous troponin values in the record for a chronic baseline. A persistent flat elevation with no rise or fall is chronic injury, not MI."},{"name":"Type 2 MI and non-ischaemic injury","see":"Raised troponin with rise and fall, no plaque-rupture story: sepsis, AF with fast ventricular response, GI bleed with Hb 60, hypoxic COPD exacerbation, hypertensive emergency, post-operative","think":"Type 2 MI (supply-demand) when there is ischaemic evidence (symptoms, ECG) alongside the stressor; acute myocardial injury when there is not. Prognosis is worse than type 1 MI because of the underlying illness, but antiplatelets and angiography are not automatically indicated.","do":"Treat the precipitant (rate control, transfuse, oxygen, antibiotics); echo; assess coronary disease electively once stable if the troponin peak was substantial or the ECG suggested ischaemia. Document the type explicitly so the patient is not labelled as having had an MI without cause."},{"name":"Pulmonary embolism, dissection and myocarditis","see":"Troponin raised with: pleuritic pain, hypoxia and tachycardia (PE); tearing pain, pulse deficit, widened mediastinum (dissection); viral prodrome, young age, diffuse ST change, raised CRP (myocarditis)","think":"PE: troponin positive in 30–50% of acute PE and marks right ventricular strain (intermediate-high risk when combined with RV dysfunction on CT or echo). Dissection: troponin rises when the right coronary ostium is involved (inferior STEMI picture), and antiplatelets or thrombolysis would be lethal. Myocarditis: troponin often very high (hundreds to thousands) with normal coronaries.","do":"CTPA or CT aortogram as the story dictates before any antithrombotic for a doubtful inferior STEMI with back pain; echo for RV strain in PE; cardiac MRI for myocarditis after coronary disease is excluded in those with risk factors."},{"name":"Chronic kidney disease and the elderly","see":"Baseline troponin above the 99th percentile in a patient with eGFR <30 or on dialysis, or over 75 with LVH or heart failure","think":"Up to 50% of dialysis patients have a persistently raised hs-TnT; the 0/1 h algorithms still work but with a lower positive predictive value and slightly lower sensitivity for rule-out. The delta is the key: a rise or fall of >20% from a known baseline suggests acute injury.","do":"Use the same algorithm, lean on serial change and the ECG, and obtain previous values; do not dismiss a chest pain story in CKD because the troponin is always high, since the MI rate in this group is higher, not lower."}],"bedside":["Pain reproduced by chest-wall palpation (LR− about 0.3), sharp or stabbing character, pleuritic or positional pain each lower the probability of MI but none excludes it; radiation to both arms (LR+ about 7), to the right arm or shoulder (LR+ about 4.7), exertional onset and diaphoresis raise it.","A third heart sound, new mitral regurgitation murmur, pulmonary crackles or hypotension with a positive troponin mark a high-risk infarction needing urgent revascularisation.","Pulse deficit or blood pressure difference >20 mmHg between arms (LR+ about 5.7), or a new diastolic murmur, with chest pain means aortic dissection: image before anticoagulating even if the troponin is raised.","Raised JVP, parasternal heave and loud P2 with hypoxia and a positive troponin suggest PE with right ventricular strain."],"pitfalls":["A single troponin below the 99th percentile at arrival in a patient presenting within 3 hours of pain onset does not exclude MI; the ESC very-low rule-out requires onset >3 h, otherwise the 1 h sample is mandatory.","Assay cut-offs are not interchangeable; a hospital switching from hs-TnT to hs-TnI, or between manufacturers, changes every threshold in the pathway. Check which assay your result came from.","Unstable angina is a troponin-negative diagnosis: a patient with crescendo rest pain and a dynamic ECG needs admission despite two negative troponins.","Macrotroponin (immunoglobulin-bound troponin), heterophile antibodies and biotin supplements (with streptavidin-based assays) can give falsely high or low results; a persistently raised troponin with a clean story and normal echo and MRI should prompt a discussion with the lab."],"src":["Byrne RA et al. 2023 ESC Guidelines for the management of acute coronary syndromes. Eur Heart J 2023;44:3720–3826 (Table: assay-specific 0/1 h and 0/2 h cut-offs)","Thygesen K et al. Fourth Universal Definition of Myocardial Infarction (2018)","NICE NG185 Acute coronary syndromes (2020); NICE DG40 High-sensitivity troponin tests for the early rule out of NSTEMI (2020)","Fanaroff AC et al. Does this patient with chest pain have acute coronary syndrome? The Rational Clinical Examination. JAMA 2015","Konstantinides SV et al. 2019 ESC Guidelines for acute pulmonary embolism (troponin and risk stratification)"]},{"id":"natriuretic","name":"Natriuretic peptides","intro":"BNP and NT-proBNP are released by stretched ventricular myocardium and answer the question the breathless patient poses at the bedside: is the heart failing, or is this lungs, anxiety or deconditioning? Their strength is ruling out: a low value makes heart failure very unlikely. Their weakness is that age, kidneys, AF and PE all raise them, and obesity lowers them.","items":[{"k":"NTproBNP","n":"NT-proBNP","ref":"Chronic or community setting (NICE NG203): <400 ng/L heart failure unlikely; 400–2000 refer for echo within 6 weeks; >2000 refer within 2 weeks. ESC chronic: <125 ng/L rules out. Acute breathlessness (ESC): <300 ng/L rules out acute heart failure; age-adjusted rule-in >450 (<50 y), >900 (50–75), >1800 (>75) ng/L","meaning":"Inactive fragment with a longer half-life (1–2 h), cleared by the kidney, so it rises more with CKD; not affected by sacubitril.","high":"Heart failure of any type (HFrEF and HFpEF), age, female sex, CKD, AF, LVH, valve disease, PE, pulmonary hypertension, sepsis, COPD exacerbation, cirrhosis, hyperthyroidism, anaemia, ischaemia, myocarditis.","low":"Obesity (BMI >35 lowers values by about half), flash pulmonary oedema within the first hour, constrictive pericarditis, mitral stenosis, treatment with diuretics, ACE inhibitors, ARBs, beta-blockers and MRAs; African or African-Caribbean ancestry."},{"k":"BNP","n":"B-type natriuretic peptide","ref":"Chronic: <35 ng/L (pg/mL) rules out (ESC); NICE NG203 uses NT-proBNP only. Acute: <100 ng/L rules out acute heart failure; >400–500 makes it likely; 100–400 grey zone","meaning":"Active hormone, half-life about 20 min; raised by sacubitril (neprilysin inhibition), so it cannot be used for monitoring on sacubitril/valsartan.","high":"As for NT-proBNP; less renal dependence.","low":"As for NT-proBNP."},{"k":"MRproANP","n":"MR-proANP","ref":"<120 pmol/L rules out acute heart failure (ESC)","meaning":"Atrial peptide alternative used in some centres; same confounders.","high":"Heart failure, AF.","low":"Obesity."}],"patterns":[{"name":"Breathless in the ED: rule-out","see":"NT-proBNP <300 ng/L or BNP <100 ng/L in acute dyspnoea","think":"Negative predictive value for acute heart failure about 98%; the breathlessness is COPD, asthma, pneumonia, PE, anxiety, anaemia or deconditioning. In an obese patient (BMI >35), halve the threshold mentally: a BNP of 80 may still be heart failure.","do":"Look elsewhere: CXR, ECG, ABG or VBG, D-dimer or CTPA where the PE story fits, peak flow, haemoglobin. Lung ultrasound (B-lines) is the bedside complement when the peptide is in the grey zone."},{"name":"Breathless in the ED: rule-in","see":"NT-proBNP above the age-adjusted cut-off (>450, >900, >1800 ng/L by age) or BNP >400–500 ng/L, with orthopnoea, raised JVP, crackles, oedema","think":"Acute heart failure likely (positive predictive value about 85–90% at these levels); then ask what type (echo: reduced versus preserved ejection fraction, valve disease) and what precipitated it (ACS, arrhythmia, infection, non-adherence, NSAIDs, uncontrolled hypertension, anaemia, thyroid). Very high values (NT-proBNP >5000) also carry prognostic weight.","do":"Diuretic, nitrate if hypertensive, CPAP if hypoxic with pulmonary oedema, ECG and troponin for a precipitating ACS, echo within 48 h (NICE NG106), start guideline therapy before discharge."},{"name":"Grey zone","see":"NT-proBNP 300–age-adjusted cut-off, or BNP 100–400, in acute dyspnoea; NT-proBNP 400–2000 in the community","think":"Heart failure in about 50% of this group; the other half are PE, AF without failure, COPD with cor pulmonale, CKD, sepsis, elderly patients with LVH. Lung ultrasound, echo and the clinical gestalt decide.","do":"Echo (within 6 weeks in the community for NICE's 400–2000 band, sooner if symptomatic); check creatinine, thyroid, haemoglobin and ECG rhythm; do not label as heart failure on the peptide alone."},{"name":"Suspected chronic heart failure in primary care","see":"Breathlessness, fatigue, ankle swelling; NICE NG203: NT-proBNP >2000 ng/L urgent referral for specialist assessment and echo within 2 weeks; 400–2000 within 6 weeks; <400 heart failure unlikely","think":"A previous MI should trigger direct referral for echo regardless of the peptide. Values below 400 with persisting symptoms still need an alternative explanation; an NT-proBNP <125 ng/L makes heart failure very unlikely in an untreated patient.","do":"Also send FBC, U&E, LFTs, TFTs, HbA1c, lipids, ECG, CXR, urinalysis and peak flow or spirometry at the same time, so the specialist has the picture."},{"name":"Raised peptide without heart failure","see":"NT-proBNP 500–3000 ng/L in AF, CKD stage 4–5, PE, sepsis or an 85-year-old without oedema","think":"Each confounder can double or treble the level; eGFR <30 roughly doubles the appropriate rule-out threshold (some use NT-proBNP <1200 ng/L in CKD). In PE, a raised BNP or NT-proBNP marks right ventricular strain and intermediate risk. In sepsis it reflects myocardial depression and carries prognostic weight.","do":"Interpret against the confounders, use the echo as arbiter, and record the result as a baseline: the change on the next presentation is more informative than the absolute number."},{"name":"Monitoring and prognosis","see":"Serial NT-proBNP in a known heart failure patient","think":"A fall of ≥30% from admission to discharge predicts fewer readmissions; a value that does not fall despite diuresis signals residual congestion or progressive disease. Routine peptide-guided therapy did not improve outcomes in GUIDE-IT, so trend it for clinical judgement, not as a target.","do":"Compare with the patient's own dry-weight baseline; BNP is uninterpretable on sacubitril/valsartan (use NT-proBNP)."}],"bedside":["Raised JVP LR+ about 3.9, third heart sound LR+ about 11 (but found in a minority), and a positive abdominojugular reflux LR+ about 6 for heart failure as the cause of dyspnoea; the peptide quantifies what these signs suggest and catches the half of cases where they are absent.","Orthopnoea (LR+ about 2) and paroxysmal nocturnal dyspnoea in the history, with bibasal crackles and peripheral oedema, map on to higher peptide levels; peripheral oedema alone is non-specific.","Lung ultrasound with ≥3 B-lines per zone bilaterally has an LR+ of about 7 for cardiogenic pulmonary oedema, complementing a grey-zone peptide.","Irregularly irregular pulse: AF raises the peptide even without heart failure, so apply the higher band and look for the failing heart on echo rather than the number."],"pitfalls":["Obesity: BMI >35 lowers BNP and NT-proBNP by around 50%; a value just under the cut-off does not exclude heart failure in an obese patient.","Renal failure: NT-proBNP rises more than BNP as eGFR falls; thresholds in dialysis patients are of limited value and echo is needed.","Timing: in flash pulmonary oedema (acute mitral regurgitation, hypertensive crisis) a sample within the first hour can be normal.","Sacubitril/valsartan raises BNP but not NT-proBNP; check the drug chart before interpreting a BNP trend."],"src":["NICE NG106 Chronic heart failure in adults: diagnosis and management (2018, with NT-proBNP thresholds); NICE NG187 Acute heart failure (2014, updated 2021)","McDonagh TA et al. 2021 ESC Guidelines for the diagnosis and treatment of acute and chronic heart failure; 2023 Focused Update","Mueller C et al. Heart Failure Association of the ESC practical guidance on the use of natriuretic peptide concentrations. Eur J Heart Fail 2019","Januzzi JL et al. NT-proBNP in the evaluation of acute dyspnoea (ICON study), age-adjusted cut-offs. Eur Heart J 2006","Martindale JL et al. Diagnosing acute heart failure in the emergency department: systematic review and meta-analysis. Acad Emerg Med 2016 (bedside LRs, lung ultrasound)"]},{"id":"d-dimer","name":"D-dimer","intro":"D-dimer is a rule-out test: a negative result in a patient with low or intermediate pre-test probability lets you stop looking for venous thromboembolism. It is sent after the probability has been estimated, not before, and never in a patient you would image regardless. A positive result in the wrong patient commits them to a CT they did not need.","items":[{"k":"DD","n":"D-dimer (fibrin degradation product)","ref":"<500 µg/L FEU (ng/mL FEU) standard; age-adjusted cut-off = age × 10 µg/L FEU for patients over 50 (a 78-year-old: 780). If your lab reports D-dimer units (DDU), the equivalent is 250 µg/L DDU and age × 5","meaning":"Cross-linked fibrin breakdown product; present whenever clot has formed and plasmin has acted, which includes most inflammatory, surgical, malignant and pregnant states.","high":"VTE, aortic dissection, DIC, sepsis, malignancy, surgery and trauma within 4 weeks, pregnancy and puerperium, age, inflammatory disease, liver disease, CKD, heart failure, AF, stroke, sickle crisis, COVID-19.","low":"Normal; falsely low with >24 h of anticoagulation, small subsegmental clots, symptoms over 1–2 weeks old, and in some DDU-reporting assays if misread as FEU."},{"k":"Wells-PE","n":"Wells score for PE (two-level)","ref":"Clinical signs of DVT 3; PE most likely diagnosis 3; HR >100 1.5; immobilisation or surgery in 4 weeks 1.5; previous VTE 1.5; haemoptysis 1; active cancer 1. >4 points PE likely (image); ≤4 PE unlikely (D-dimer)","meaning":"NICE NG158 pathway: likely goes straight to CTPA (or interim anticoagulation if delay); unlikely goes to D-dimer.","high":"Score >4: D-dimer is not needed and a negative result should not reassure.","low":"Score ≤4 with negative D-dimer: PE excluded (3-month VTE rate <1%)."},{"k":"YEARS","n":"YEARS algorithm","ref":"Three items: clinical signs of DVT, haemoptysis, PE the most likely diagnosis. No items: D-dimer <1000 µg/L FEU excludes PE. One or more items: D-dimer <500 excludes","meaning":"Simplifies and raises the threshold in low-probability patients, cutting CTPA by about 14% without missing more PE; validated in pregnancy (pregnancy-adapted YEARS with compression ultrasound if leg symptoms).","high":"Any item present lowers the acceptable D-dimer to 500 (or age-adjusted in some protocols).","low":"No items and D-dimer <1000: stop."},{"k":"PERC","n":"Pulmonary embolism rule-out criteria","ref":"Age <50, HR <100, SpO2 ≥95% on air, no haemoptysis, no oestrogen use, no previous VTE, no unilateral leg swelling, no surgery or trauma requiring hospitalisation in the past 4 weeks. All eight negative, in a patient whose clinician gestalt probability is <15%, means no D-dimer needed","meaning":"Avoids the test entirely in the very low-risk young patient with pleuritic pain or breathlessness; PE missed rate about 1% in validation (PROPER trial).","high":"Any criterion present: PERC cannot be applied; proceed to Wells and D-dimer.","low":"All negative and gestalt low: no D-dimer, no imaging."},{"k":"Wells-DVT","n":"Wells score for DVT","ref":"≥2 points DVT likely (proximal leg vein ultrasound within 4 h, or D-dimer and interim anticoagulation if delayed); ≤1 DVT unlikely (D-dimer; if positive, ultrasound)","meaning":"Items: active cancer, paralysis or recent cast, bedridden >3 days or major surgery in 12 weeks, localised tenderness along the deep veins, entire leg swollen, calf >3 cm larger, pitting oedema in the symptomatic leg, collateral superficial veins, previous DVT; minus 2 for an alternative diagnosis at least as likely.","high":"≥2: image.","low":"≤1 with negative D-dimer: DVT excluded."}],"patterns":[{"name":"PE unlikely, D-dimer negative","see":"Wells ≤4 (or YEARS 0 items with D-dimer <1000, or any items with <500, or age-adjusted negative)","think":"PE excluded with a 3-month VTE risk under 1%, comparable to a negative CTPA. Reconsider the differential: pleurisy, musculoskeletal, pneumothorax, pneumonia, pericarditis, ACS, anxiety.","do":"Document the score and the threshold used; no imaging, no anticoagulation; safety-net for worsening breathlessness, syncope or haemoptysis."},{"name":"PE unlikely, D-dimer positive","see":"Wells ≤4 with D-dimer above threshold","think":"PE is present in about 10–15% of this group; the rest are false positives from age, infection, cancer or recent surgery. The test has done its job of selecting for imaging; it cannot do more.","do":"CTPA (or V/Q SPECT in pregnancy, contrast allergy or renal impairment); offer interim anticoagulation if imaging will be delayed beyond 4 h (NICE NG158). Do not repeat the D-dimer hoping for a lower value."},{"name":"PE likely","see":"Wells >4, or a gestalt that says PE (syncope, hypoxia, tachycardia, unilateral leg swelling, recent surgery)","think":"D-dimer should not be sent: a negative result does not lower the probability enough to stop (post-test probability remains around 5–10%), and a positive adds nothing.","do":"Straight to CTPA; interim anticoagulation if delay; bedside echo for RV strain if hypotensive, and consider thrombolysis for high-risk PE with shock."},{"name":"Age-adjusted D-dimer in the elderly","see":"Patient over 50 with Wells ≤4 and D-dimer between 500 and age × 10 µg/L FEU","think":"Using the age-adjusted cut-off increases the proportion of over-75s ruled out from about 6% to 30%, with a 3-month VTE rate of 0.3% (ADJUST-PE). NICE NG158 says consider age-adjusted thresholds for over-50s. Confirm your lab's units (FEU versus DDU) before applying it.","do":"PE excluded if below the age-adjusted threshold; otherwise image."},{"name":"When not to send a D-dimer","see":"High pre-test probability; patient already anticoagulated >24 h; symptoms over 2 weeks; inpatient with sepsis, cancer or recent surgery; pregnancy without a validated pathway; chest pain where PE was never a serious consideration; as a screen for unexplained tachycardia","think":"In these settings the test is either falsely reassuring (anticoagulated, high probability) or almost always positive (post-operative, cancer, sepsis, third trimester) and converts to an avoidable CT. A positive D-dimer in a patient without a PE story generates a cascade.","do":"Estimate probability first; if the patient will be imaged anyway, image; if PE is not on the differential, do not test. In pregnancy use the pregnancy-adapted YEARS or go to imaging per local protocol (RCOG Green-top 37b)."},{"name":"Aortic dissection","see":"Acute chest or back pain with any Aortic Dissection Detection Risk Score feature (Marfan, known aneurysm, tearing pain, pulse deficit, new aortic regurgitation, hypotension)","think":"D-dimer <500 µg/L within 24 h of onset has a sensitivity of about 97% and LR− about 0.05 for dissection; ADD-RS ≤1 plus negative D-dimer (ADvISED) safely rules out in low-to-moderate risk. It cannot replace CT in high-risk patients (ADD-RS ≥2) or those presenting late, and thrombosed false lumens can be D-dimer negative.","do":"ADD-RS ≥2 or any high-risk feature: CT aortogram regardless. ADD-RS 0–1: D-dimer <500 reasonably excludes; otherwise CT."},{"name":"Disseminated intravascular coagulation","see":"Very high D-dimer with falling platelets, prolonged PT, low fibrinogen in a septic, obstetric or malignant patient","think":"D-dimer is the fibrin-degradation item in the ISTH DIC score; see the coagulation panel. A D-dimer in the tens of thousands with bleeding and thrombosis is the DIC picture, not a VTE question.","do":"ISTH score, treat the cause, replace what is bleeding (platelets, FFP, cryoprecipitate), haematology discussion."}],"bedside":["Unilateral calf swelling with a difference ≥3 cm at 10 cm below the tibial tuberosity (LR+ about 2) and pitting oedema in one leg support DVT; Homan's sign is unreliable and should not be elicited.","Tachycardia >100 (LR+ about 1.5), SpO2 <95% on air, pleural rub and signs of DVT shift the pre-test probability; a normal examination with a normal SpO2 does not exclude PE.","Syncope with tachycardia, raised JVP, parasternal heave or hypotension suggests a large PE and needs imaging and bedside echo, not a D-dimer.","Inter-arm BP difference >20 mmHg, pulse deficit or a new early diastolic murmur with chest pain shifts the question from PE to dissection; the D-dimer is used differently."],"pitfalls":["Units: FEU and DDU assays differ by a factor of two; 500 µg/L FEU equals 250 µg/L DDU. Applying the FEU threshold to a DDU result misses clots; applying age-adjustment in DDU units requires age × 5.","Anticoagulation for more than 24 hours (including a prophylactic LMWH dose in an inpatient) halves the D-dimer and makes a negative result unreliable.","A D-dimer sent as a screen in a patient with no PE story has a specificity of 40–60% in older and hospitalised patients; it generates a CTPA in half of them with a PE yield under 5%.","Subsegmental and chronic PE can be D-dimer negative; a patient with persistent unexplained hypoxia, tachycardia or right heart strain still needs imaging."],"src":["NICE NG158 Venous thromboembolic diseases: diagnosis, management and thrombophilia testing (2020, updated 2023)","Righini M et al. Age-adjusted D-dimer cutoff levels to rule out pulmonary embolism: the ADJUST-PE study. JAMA 2014","van der Hulle T et al. Simplified diagnostic management of suspected PE (the YEARS study). Lancet 2017; van der Pol LM et al. Pregnancy-adapted YEARS. NEJM 2019","Freund Y et al. Effect of the PERC rule on safety of ED discharge (PROPER). JAMA 2018; Kline JA et al. PERC derivation. J Thromb Haemost 2004","Nazerian P et al. Diagnostic accuracy of the ADD-RS plus D-dimer for acute aortic syndromes (ADvISED). Circulation 2018; Konstantinides SV et al. 2019 ESC Guidelines for acute pulmonary embolism"]},{"id":"lactate","name":"Lactate","intro":"Lactate is the bedside marker of tissue hypoperfusion and the number that turns a clinical impression of sepsis or shock into a measurable one. A raised lactate confirms that the cold peripheries, the tachycardia and the confusion mean the tissues are short of oxygen or unable to use it; a falling lactate confirms that resuscitation is working. The trap is that lactate also rises for reasons that have nothing to do with perfusion.","items":[{"k":"Lac","n":"Lactate (venous or arterial)","ref":"0.5–2.0 mmol/L (4.5–18 mg/dL); >2 hyperlactataemia; >4 severe and associated with high mortality in sepsis","meaning":"Product of anaerobic glycolysis and of accelerated aerobic glycolysis under adrenergic drive; cleared by liver (60%) and kidney, so clearance fails in liver disease.","high":"Type A (hypoperfusion or hypoxia): shock of any cause, severe hypoxaemia, severe anaemia, carbon monoxide, cyanide, regional ischaemia (mesenteric, limb), seizures and extreme exercise. Type B (no hypoperfusion): sepsis (adrenergic drive and mitochondrial dysfunction), metformin, beta-agonists (salbutamol nebulisers), adrenaline infusion, thiamine deficiency, liver failure, malignancy (lymphoma, leukaemia: Warburg effect), alcohol and ketoacidosis, propofol infusion syndrome, linezolid, nucleoside reverse transcriptase inhibitors, paracetamol overdose, D-lactate from short bowel.","low":"No clinical significance."},{"k":"Lac-clear","n":"Lactate clearance","ref":"Fall of ≥10–20% at 2 h, or normalisation (<2) within 6 h, after resuscitation","meaning":"Trajectory beats the single value; failure to clear within 6 h despite fluids and source control predicts death and demands re-examination for a missed source or ongoing ischaemia.","high":"Rising or static lactate: inadequate resuscitation, uncontrolled source, ischaemic bowel or limb, liver failure, ongoing drug effect.","low":"Rapid clearance after a seizure or exercise (within 1–2 h) is reassuring and expected."},{"k":"Lac-VBG","n":"Venous versus arterial lactate","ref":"Peripheral venous lactate agrees with arterial to within about 0.3 mmol/L at values under 4; agreement worsens above that and with a tourniquet","meaning":"A venous lactate is adequate to screen and to trend; an arterial sample is needed only if the value changes management and the venous result is unexpected.","high":"Tourniquet left on, fist clenching, difficult draw and delayed analysis (>15 min at room temperature) all raise the venous value.","low":"Not applicable."}],"patterns":[{"name":"Sepsis and septic shock","see":"Suspected infection with lactate >2 mmol/L (Sepsis-3 septic shock: vasopressors needed to keep MAP ≥65 plus lactate >2 despite adequate fluid). NICE NG51 uses lactate >4 as a high-risk criterion, 2–4 as moderate","think":"In sepsis lactate rises from both hypoperfusion and adrenergic-driven glycolysis, so it reflects severity more than oxygen debt; mortality rises stepwise with lactate >2, >4 and with failure to clear. A normal lactate does not exclude sepsis: about 30–40% of patients with septic shock have lactate <2 on arrival (cryptic shock is the reverse: normal BP, high lactate, same mortality).","do":"Sepsis Six within the hour: oxygen if needed, cultures, antibiotics, 30 mL/kg crystalloid for lactate ≥4 or hypotension (Surviving Sepsis 2021), lactate repeat within 2–4 h, urine output. Vasopressors (noradrenaline) if MAP <65 after fluid. Lactate not clearing at 6 h: senior review, source imaging, surgical opinion."},{"name":"Type A: occult hypoperfusion","see":"Lactate >4 with normal or borderline blood pressure, cool mottled peripheries, prolonged capillary refill, narrow pulse pressure, oliguria","think":"Cryptic shock: haemorrhage not yet hypotensive (young patients compensate), cardiogenic shock (cold and wet), early septic shock, mesenteric ischaemia (lactate rises late and may be normal early, pain out of proportion to signs), limb ischaemia, cardiac tamponade.","do":"Treat the lactate as if it were hypotension: find the cause (bedside echo for pump and tamponade, FAST for blood, examine for a tense abdomen or a pulseless limb), resuscitate, and repeat the lactate at 2 h. A mottling score extending beyond the kneecap predicts mortality independently of lactate."},{"name":"Type B: lactate without shock","see":"Lactate 2–6 in a warm, well-perfused patient","think":"Recent seizure (clears within 1–2 h), salbutamol nebulisers in asthma (lactate 2–5 is usual with back-to-back nebulisers and does not mean the asthma is worse), adrenaline, metformin, alcohol, thiamine deficiency (give thiamine before glucose), malignancy, liver disease, HIV drugs, paracetamol poisoning (early raised lactate with high levels indicates severity), diabetic ketoacidosis.","do":"Correct the cause if possible, recheck; treat as type A if any perfusion doubt. A persistently raised type B lactate in a cancer patient or a patient on linezolid is a reason to discuss the drug or the disease, not to give fluids."},{"name":"Metformin-associated lactic acidosis","see":"Lactate >5 mmol/L with arterial pH <7.35 in a patient on metformin, usually with AKI, dehydration, sepsis or contrast exposure, or after deliberate overdose","think":"Rare (about 3–10 per 100 000 patient-years) but 30–50% mortality; metformin accumulates when the kidney fails and blocks hepatic gluconeogenesis from lactate. The lactate is often strikingly high (10–20) with a low bicarbonate and raised anion gap; the patient is often vomiting, confused, with abdominal pain and hypothermia.","do":"Stop metformin, treat the precipitant, bicarbonate if pH <7.1, and early haemodialysis (clears metformin and lactate; EXTRIP criteria: lactate >20, pH ≤7.0, or failure of standard therapy, shock, reduced consciousness). Withhold metformin when eGFR <30, during acute illness with dehydration, and for 48 h after iodinated contrast if eGFR <60 (sick day rules)."},{"name":"Lactate with raised anion gap","see":"Metabolic acidosis with anion gap >12 and lactate explaining most of the gap","think":"Lactate and ketones together account for most raised-gap acidoses in the ED; if the lactate and ketones do not explain the gap, think toxic alcohols (osmolar gap), salicylates, pyroglutamic acid (paracetamol in chronic use with sepsis or flucloxacillin), uraemia, D-lactate (standard assay does not detect it; short bowel with confusion).","do":"Calculate the gap and the delta ratio (see blood gas panel); send paracetamol, salicylate, ketones, osmolality; treat the cause rather than the number."},{"name":"Trauma and haemorrhage","see":"Lactate >2.5 and base deficit >6 in a trauma patient with a normal blood pressure","think":"Lactate and base deficit are the earliest markers of haemorrhagic shock and of transfusion need; they rise before the blood pressure falls in the young and the beta-blocked. Normalisation within 24 h predicts survival.","do":"Activate massive haemorrhage protocol thresholds locally; repeat at 2 h and use clearance as the resuscitation endpoint alongside urine output and mental state."}],"bedside":["Capillary refill >2 s, skin mottling over the knees and a cool, clammy periphery reflect the same hypoperfusion the lactate measures; capillary refill time-guided resuscitation was non-inferior to lactate-guided in ANDROMEDA-SHOCK, so the two are complementary.","A patient on back-to-back salbutamol with a lactate of 4 is not necessarily getting worse; look at the peak flow, respiratory rate and ability to speak before escalating on the number.","Post-ictal patients commonly have a lactate of 5–10 that clears within 2 h; a persistently raised lactate after a seizure suggests a continuing cause, status, or a different diagnosis.","Abdominal pain out of proportion to tenderness in an older patient with AF and a raised lactate is mesenteric ischaemia until CT angiography says otherwise, but a normal lactate does not exclude it early."],"pitfalls":["Normal lactate does not exclude shock, sepsis or mesenteric ischaemia; cryptic shock and early ischaemia both run on the normal side for hours.","Tourniquet time, fist clenching, difficult venepuncture and a sample left >15 minutes at room temperature all raise the venous lactate spuriously; repeat with a free-flowing sample if the value does not fit the patient.","Lactated Ringer's (Hartmann's) does not raise the lactate meaningfully in a patient with normal liver function, and bicarbonate does not lower it; treating the number rather than the cause is the error.","Lactate clearance is impaired in liver failure and in alcoholics, so a slow fall may reflect poor clearance rather than ongoing hypoperfusion; thiamine 300 mg IV is harmless and sometimes the treatment."],"src":["Evans L et al. Surviving Sepsis Campaign: international guidelines for management of sepsis and septic shock 2021. Crit Care Med 2021","Singer M et al. The Third International Consensus Definitions for Sepsis and Septic Shock (Sepsis-3). JAMA 2016","NICE NG51 Sepsis: recognition, diagnosis and early management (updated 2024)","Kraut JA, Madias NE. Lactic acidosis. NEJM 2014; Calello DP et al. Extracorporeal treatment for metformin poisoning: EXTRIP recommendations. Crit Care Med 2015","Hernández G et al. Effect of a resuscitation strategy targeting peripheral perfusion status vs serum lactate levels (ANDROMEDA-SHOCK). JAMA 2019"]},{"id":"blood-gas","name":"Blood gas","intro":"A blood gas confirms what the breathing pattern and the mental state suggested: whether the patient is retaining CO2, whether there is an acid load and of what kind, and whether oxygenation is failing. Read it in a fixed order every time (the Buffer app teaches the same five steps), because the gas that misleads is the one read as a single number. A venous gas answers the acid–base and CO2 questions for most ward and ED patients; an arterial gas is needed for oxygenation and for precision in the sickest.","items":[{"k":"pH","n":"pH","ref":"7.35–7.45 (H⁺ 35–45 nmol/L)","meaning":"The net result; acidaemia or alkalaemia names the dominant process even when several coexist.","high":"Alkalaemia: respiratory (hyperventilation) or metabolic (vomiting, diuretics, hypokalaemia).","low":"Acidaemia: respiratory (hypoventilation) or metabolic (lactate, ketones, renal, diarrhoea, toxins)."},{"k":"pCO2","n":"Arterial pCO2","ref":"4.7–6.0 kPa (35–45 mmHg)","meaning":"The respiratory variable: set by alveolar ventilation. Rises when ventilation fails, falls as compensation for metabolic acidosis or with anxiety, pain, PE and sepsis.","high":"Respiratory acidosis: COPD, opioid or sedative toxicity, neuromuscular weakness, obesity hypoventilation, severe asthma (a normal or rising pCO2 in acute asthma is a pre-arrest sign), exhaustion.","low":"Respiratory alkalosis or compensation: pain, anxiety, PE, pneumonia, sepsis, salicylates, pregnancy, liver failure, high altitude."},{"k":"HCO3","n":"Bicarbonate (calculated) and base excess","ref":"HCO3 22–26 mmol/L; base excess −2 to +2","meaning":"The metabolic variable: falls with acid gain or bicarbonate loss, rises with acid loss or chronic CO2 retention. Base excess strips out the respiratory contribution.","high":"Metabolic alkalosis: vomiting, nasogastric loss, diuretics, hypokalaemia, mineralocorticoid excess; or compensation for chronic hypercapnia (rises about 3.5 mmol/L per 1.3 kPa (10 mmHg) chronic pCO2 rise).","low":"Metabolic acidosis; or compensation for chronic hypocapnia."},{"k":"pO2","n":"Arterial pO2","ref":"11–13 kPa (80–100 mmHg) on room air in the young; expected about 13.3 − (age ÷ 30) kPa; roughly FiO2 (%) minus 10 in kPa on supplemental oxygen","meaning":"Oxygenation. Type 1 respiratory failure: pO2 <8 kPa (60 mmHg) with normal or low pCO2; type 2: pO2 <8 with pCO2 >6 kPa (45 mmHg).","high":"Supplemental oxygen; a pO2 of 30 on 15 L is normal, not a reason to continue 15 L.","low":"V/Q mismatch (pneumonia, PE, pulmonary oedema, COPD), shunt (ARDS, atelectasis, intracardiac), hypoventilation (with raised pCO2), diffusion limitation, low FiO2."},{"k":"AG","n":"Anion gap","ref":"Na − (Cl + HCO3) = 8–12 mmol/L (4–12 if K excluded; some labs 8–16 with K). Albumin-corrected gap = measured + 2.5 × (40 − albumin in g/L) ÷ 10","meaning":"Unmeasured anions; a raised gap means an acid has been added (lactate, ketones, sulphate and phosphate in renal failure, toxic alcohol metabolites, salicylate, pyroglutamate). A normal-gap acidosis means bicarbonate was lost (diarrhoea, RTA, saline, acetazolamide, ureteric diversion).","high":"GOLDMARK: glycols (ethylene, propylene), oxoproline (pyroglutamic acid), L-lactate, D-lactate, methanol, aspirin, renal failure, ketoacidosis.","low":"Hypoalbuminaemia (each 10 g/L fall in albumin lowers the gap by about 2.5), paraproteins, lithium, bromide; an uncorrected gap hides acidosis in the hypoalbuminaemic ICU patient."},{"k":"VBG","n":"Venous gas offsets","ref":"Venous pH about 0.03–0.04 lower, pCO2 about 0.5–0.8 kPa (4–6 mmHg) higher, HCO3 about 1–2 mmol/L higher than arterial; venous pO2 uninterpretable","meaning":"A venous pCO2 under 6 kPa (45 mmHg) effectively excludes arterial hypercapnia; a venous pCO2 above that needs an arterial sample if the result would change ventilation decisions. Agreement for pH and HCO3 is good enough to diagnose DKA and monitor its treatment.","high":"Central venous samples run closer to arterial than peripheral; shock widens the venous–arterial gap.","low":"Not applicable."},{"k":"PF","n":"PaO2/FiO2 ratio and A–a gradient","ref":"P/F >40 kPa (300 mmHg) normal; ARDS mild 26.7–40 kPa (200–300), moderate 13.3–26.7 (100–200), severe ≤13.3 (≤100) on PEEP ≥5; A–a gradient on air normally <(age ÷ 4 + 4) mmHg, about 1–2 kPa in the young","meaning":"P/F quantifies oxygenation failure independent of the oxygen given; the A–a gradient separates hypoventilation (normal gradient) from lung disease (raised gradient).","high":"A raised A–a gradient with a low pO2 means parenchymal, vascular or shunt disease (PE with a clear chest X-ray and raised gradient is a classic clue).","low":"A normal gradient with hypoxia means hypoventilation or low inspired oxygen."}],"patterns":[{"name":"The five-step read","see":"Any gas","think":"1. pH: acidaemia (<7.35) or alkalaemia (>7.45). 2. Primary process: does the pCO2 or the HCO3 move in the direction that explains the pH (respiratory if pCO2 explains it, metabolic if HCO3 does)? 3. Compensation: is it appropriate? For metabolic acidosis the expected pCO2 (Winter's formula) is 1.5 × HCO3 + 8 ± 2 mmHg, or 0.2 × HCO3 + 1.1 ± 0.3 kPa; if the measured pCO2 is higher there is an additional respiratory acidosis (the patient is tiring), if lower an additional respiratory alkalosis (salicylate, sepsis). Acute respiratory acidosis: HCO3 rises 1 mmol/L per 1.3 kPa (10 mmHg) pCO2 rise; chronic: 3.5 per 10 mmHg. 4. Anion gap, albumin-corrected; if raised, the delta ratio (rise in AG ÷ fall in HCO3): <0.4 pure normal-gap acidosis, 0.4–0.8 mixed, 1–2 pure raised-gap, >2 concurrent metabolic alkalosis or prior chronic respiratory acidosis. 5. Oxygenation: pO2 against FiO2, P/F ratio, A–a gradient. Then look at the extras on the strip: lactate, glucose, potassium, haemoglobin, carboxyhaemoglobin, methaemoglobin.","do":"Write the interpretation as a sentence (for example: metabolic acidosis with raised anion gap, appropriate respiratory compensation, type 1 respiratory failure, lactate 6) before deciding anything; the sentence is what you hand over."},{"name":"Raised anion gap metabolic acidosis","see":"pH <7.35, HCO3 <22, AG >12 (albumin-corrected)","think":"Lactate (shock, sepsis, metformin, seizures), ketones (DKA, alcoholic, starvation: measure blood β-hydroxybutyrate), renal failure (urea and phosphate high), toxic alcohols (osmolar gap >10 mOsm/kg: calculated osmolality 2Na + glucose + urea, in mmol/L), salicylate (with respiratory alkalosis), pyroglutamic acid (chronic paracetamol, flucloxacillin, malnutrition, sepsis). A delta ratio >2 signals an added alkalosis (vomiting in DKA) and a ratio <1 an added normal-gap acidosis (saline resuscitation).","do":"Lactate, ketones, glucose, U&E, paracetamol and salicylate levels, osmolality; treat the cause. Bicarbonate is reserved for pH <7.1 with haemodynamic compromise or for specific toxins (salicylate, tricyclics)."},{"name":"Normal anion gap (hyperchloraemic) metabolic acidosis","see":"pH <7.35, HCO3 low, AG 8–12, chloride high","think":"Bicarbonate lost from the gut (diarrhoea, ileostomy, fistula) or the kidney (RTA types 1, 2 and 4, acetazolamide, early renal failure), or chloride gained (large volumes of 0.9% saline, ammonium chloride). The urine anion gap (Na + K − Cl) is negative in gut loss (ammonium being excreted appropriately) and positive in RTA.","do":"History of diarrhoea or stoma output, fluid chart for saline, urine pH (>5.5 in distal RTA despite acidosis), potassium (high in type 4 RTA, low in types 1 and 2); switch to balanced crystalloid."},{"name":"Respiratory acidosis: acute versus chronic","see":"pH <7.35 with pCO2 >6 kPa (45 mmHg)","think":"Acute (HCO3 near normal, pH markedly low): opioids, sedatives, severe asthma, exhaustion, neuromuscular crisis, obstruction: the patient needs ventilatory support or reversal now. Chronic (HCO3 >30, pH near normal): COPD, obesity hypoventilation, kyphoscoliosis; the raised bicarbonate is the clue that this is the patient's baseline. Acute-on-chronic: HCO3 raised but pH still low.","do":"COPD exacerbation with pH <7.35 and pCO2 >6.5 kPa after 1 h of optimal medical therapy on controlled oxygen (target SpO2 88–92%): NIV (BTS/ICS 2016). pH <7.25 or falling consciousness: discuss intubation. Naloxone for opioid toxicity; a normal pCO2 in a patient with severe acute asthma is a sign of tiring, not reassurance."},{"name":"Metabolic alkalosis","see":"pH >7.45 with HCO3 >26; compensatory pCO2 rises 0.7 mmHg (0.1 kPa) per 1 mmol/L HCO3, rarely above 7.3 kPa (55 mmHg)","think":"Chloride-responsive (urine chloride <20 mmol/L: vomiting, NG suction, diuretics after they wear off, post-hypercapnia) versus chloride-resistant (urine chloride >20: hyperaldosteronism, Cushing's, Bartter and Gitelman, severe hypokalaemia, excess alkali). Hypokalaemia and hypochloraemia maintain it.","do":"Replace chloride (0.9% saline) and potassium for the responsive group; treat the cause for the resistant group. Pyloric stenosis in an infant and persistent vomiting in an adult give the classic hypochloraemic hypokalaemic alkalosis."},{"name":"Mixed disorders the compensation formulas expose","see":"Compensation outside the expected range","think":"Salicylate poisoning: primary respiratory alkalosis plus raised-gap metabolic acidosis (pCO2 lower than Winter's predicts). Sepsis: metabolic acidosis with respiratory alkalosis. Tiring asthmatic or COPD patient with lactate: metabolic acidosis with respiratory acidosis, pH plunging. DKA with vomiting: raised-gap acidosis with metabolic alkalosis (delta ratio >2, HCO3 less low than expected). Cardiac arrest: combined respiratory and metabolic acidosis.","do":"Name each component; mixed disorders are where the single-number reader is caught out and where the treatment often differs (the salicylate patient must not be allowed to hypoventilate on intubation)."},{"name":"Hypoxaemia with a clear chest","see":"pO2 <8 kPa with raised A–a gradient, normal chest X-ray, normal or low pCO2","think":"PE, early pneumocystis or viral pneumonitis, early ARDS, intracardiac or intrapulmonary shunt (platypnoea), hepatopulmonary syndrome, methaemoglobinaemia (saturation stuck around 85% with chocolate-brown blood and a normal pO2 on the gas), carbon monoxide (normal pO2 and SpO2 with high COHb on co-oximetry).","do":"Co-oximetry on the gas, CTPA if PE fits, echo with bubble study for shunt, methylene blue for methaemoglobinaemia >20–30% or symptomatic, high-flow oxygen for CO."}],"bedside":["Kussmaul breathing (deep, sighing, regular) is the visible compensation for metabolic acidosis; its absence in a patient with HCO3 of 8 means they are not compensating and the pCO2 will confirm a mixed picture.","CO2 retention flap (asterixis), bounding pulse, warm peripheries, headache and drowsiness point to acute hypercapnia; a chronically hypercapnic COPD patient may look well with a pCO2 of 8 kPa, and the raised bicarbonate on the gas is what tells you it is chronic.","Cyanosis needs about 50 g/L of deoxygenated haemoglobin, so it appears late in hypoxaemia and not at all in severe anaemia; the gas, not the lips, measures oxygenation.","Silent chest, inability to complete sentences and exhaustion in asthma precede the rise in pCO2; the gas confirms what the bedside already decided."],"pitfalls":["A normal pH does not mean a normal gas: a pH of 7.40 with pCO2 of 8 kPa and HCO3 of 36 is chronic respiratory acidosis with full compensation, and a pH of 7.40 with low HCO3 and low pCO2 can be a mixed acidosis and alkalosis.","Forgetting to correct the anion gap for albumin hides a raised-gap acidosis in the hypoalbuminaemic patient; a measured gap of 10 with an albumin of 20 g/L is a corrected gap of 15.","Air bubbles raise pO2 and lower pCO2; a delayed sample (>15 min unchilled) lowers pO2 and pH and raises lactate. Heparin dilution lowers all values and HCO3.","Pulse oximetry reads carboxyhaemoglobin as oxyhaemoglobin and is unreliable in methaemoglobinaemia, dark skin at low saturations, poor perfusion and nail varnish; the gas with co-oximetry is the arbiter when the SpO2 and the patient disagree."],"src":["Berend K, de Vries APJ, Gans ROB. Physiological approach to assessment of acid–base disturbances. NEJM 2014","Davidson AC et al. BTS/ICS guideline for the ventilatory management of acute hypercapnic respiratory failure in adults. Thorax 2016","O'Driscoll BR et al. BTS guideline for oxygen use in adults in healthcare and emergency settings. Thorax 2017","Kraut JA, Madias NE. Serum anion gap: its uses and limitations in clinical medicine. Clin J Am Soc Nephrol 2007; Mehta AN et al. GOLD MARK: an anion gap mnemonic for the 21st century. Lancet 2008","Matthay MA et al. A new global definition of acute respiratory distress syndrome. Am J Respir Crit Care Med 2024; Bloom BM et al. The role of venous blood gas in the emergency department: a systematic review. Eur J Emerg Med 2014"]},{"id":"glucose-hba1c","name":"Glucose and HbA1c","intro":"Glucose is the first number to check in any confused, sweaty, seizing or unresponsive patient, because hypoglycaemia mimics everything and is instantly reversible. HbA1c converts a single reading into a three-month average and makes the diagnosis of diabetes; ketones and the gas convert high glucose into DKA or HHS, two emergencies with different fluid and insulin needs.","items":[{"k":"Gluc","n":"Plasma glucose","ref":"Fasting 3.9–5.5 mmol/L (70–99 mg/dL); random <7.8 (140). Diagnostic of diabetes (WHO/ADA): fasting ≥7.0 (126), 2 h OGTT ≥11.1 (200), random ≥11.1 with symptoms; repeat on another day if asymptomatic","meaning":"Conversion: mmol/L × 18 = mg/dL.","high":"Diabetes, stress hyperglycaemia (sepsis, MI, stroke, steroids), Cushing's, pancreatitis, antipsychotics, thiazides, total parenteral nutrition.","low":"Insulin and sulfonylureas (commonest), alcohol, liver failure, sepsis, adrenal insufficiency, insulinoma, non-islet tumours, post-bariatric dumping, factitious; <4 mmol/L in a person on insulin or sulfonylurea is hypoglycaemia (four is the floor)."},{"k":"HbA1c","n":"Glycated haemoglobin","ref":"Normal <42 mmol/mol (<6.0%); non-diabetic hyperglycaemia 42–47 (6.0–6.4%) in UK guidance (ADA prediabetes 39–47, 5.7–6.4%); diabetes ≥48 (≥6.5%), repeated if asymptomatic","meaning":"Average glycaemia over 8–12 weeks, weighted to the last month; conversion: % = (mmol/mol ÷ 10.93) + 2.15.","high":"Diabetes; falsely high in iron, B12 and folate deficiency anaemia, splenectomy, CKD (carbamylation), alcohol, some haemoglobinopathies by assay.","low":"Falsely low with shortened red-cell survival: haemolysis, recent transfusion or blood loss, EPO or iron treatment, pregnancy (second and third trimester), HIV antiretrovirals, hypersplenism, some haemoglobin variants."},{"k":"Ket","n":"Blood ketones (β-hydroxybutyrate)","ref":"<0.6 mmol/L normal; 0.6–1.5 at risk, repeat; ≥1.5 risk of DKA; ≥3.0 DKA threshold with acidosis","meaning":"Capillary β-hydroxybutyrate is the ketone of DKA; the urine dipstick measures acetoacetate and lags both the onset and the resolution.","high":"DKA (type 1, ketosis-prone type 2, SGLT2 inhibitors with normal glucose), alcoholic ketoacidosis, starvation and ketogenic diets (rarely >3), pregnancy vomiting.","low":"Not applicable."},{"k":"Osm","n":"Serum osmolality","ref":"275–295 mOsm/kg; calculated = 2 × Na + glucose + urea (mmol/L)","meaning":"Defines HHS (≥320) and explains the obtundation in severe hyperglycaemia; the osmolar gap flags toxic alcohols.","high":"HHS, hypernatraemia, uraemia, toxic alcohols, mannitol.","low":"Hyponatraemia."},{"k":"Ins-Cpep","n":"Insulin and C-peptide during hypoglycaemia","ref":"During a hypoglycaemic episode (glucose <3.0 mmol/L, 55 mg/dL): insulin ≥18 pmol/L (3 mU/L) and C-peptide ≥0.2 nmol/L (0.6 ng/mL) inappropriate","meaning":"Taken at the time of Whipple's triad in a non-diabetic patient, they separate insulinoma and sulfonylurea (both C-peptide high) from exogenous insulin (C-peptide suppressed).","high":"Insulinoma, sulfonylurea or meglitinide ingestion (send a drug screen), insulin autoimmune syndrome.","low":"Exogenous insulin (insulin high, C-peptide low), or appropriate suppression in non-insulin-mediated hypoglycaemia (liver failure, adrenal insufficiency, sepsis, non-islet tumour)."}],"patterns":[{"name":"Diabetic ketoacidosis","see":"JBDS 2023: ketonaemia ≥3.0 mmol/L (or urine ketones ≥2+), blood glucose >11.1 mmol/L (200 mg/dL) or known diabetes, and bicarbonate <15 mmol/L and/or venous pH <7.3. The 2024 ADA/EASD consensus uses the same ketone threshold with bicarbonate <18 and/or pH <7.3. Severe DKA: ketones >6, bicarbonate <5, pH <7.0, potassium <3.5 on admission, GCS <12, SpO2 <92%, systolic <90, pulse >100 or <60, anion gap >16","think":"Precipitants: infection (30–40%), missed insulin, new type 1, MI, pancreatitis, SGLT2 inhibitors (euglycaemic DKA with glucose <14 in 10–15% of cases on these drugs), steroids, antipsychotics, cocaine. Abdominal pain, vomiting and Kussmaul breathing are the bedside picture; a raised amylase and WCC are common without pancreatitis or infection.","do":"Fixed-rate IV insulin 0.1 units/kg/h after fluid is running (0.9% saline 1 L over the first hour, 1 L over 2 h, 1 L over 2 h, 1 L over 4 h, then 1 L over 4–6 h, slower in the elderly and cardiac failure), potassium in the second litre once K <5.5 (40 mmol/L if 3.5–5.5; senior review if <3.5), continue the patient's basal insulin, add 10% glucose when glucose falls below 14 mmol/L; monitor capillary ketones and glucose hourly and venous gas at 1, 2, 4, 6 h aiming for ketones falling ≥0.5 mmol/L/h and bicarbonate rising ≥3 mmol/L/h. Resolution: ketones <0.6 and pH >7.3; convert to subcutaneous insulin with an overlap."},{"name":"Hyperosmolar hyperglycaemic state","see":"JBDS 2022: hypovolaemia, glucose ≥30 mmol/L (540 mg/dL) without significant ketonaemia (<3.0) or acidosis (pH ≥7.3, bicarbonate ≥15), and osmolality ≥320 mOsm/kg (calculated 2Na + glucose + urea). ADA/EASD 2024: glucose ≥33.3 mmol/L (600 mg/dL), effective osmolality >300 or total >320","think":"Older type 2 patients, develops over days, fluid deficit 100–220 mL/kg, mortality 10–20%; precipitated by infection, MI, stroke, steroids, thiazides, reduced access to water. Mixed DKA-HHS occurs in about a third. Thrombosis and foot ulceration are the complications to search for.","do":"0.9% saline first, aiming for a positive balance of 2–3 L by 6 h and 3–6 L by 12 h; measure or calculate osmolality hourly and aim for a fall of 3–8 mOsm/kg/h and glucose fall ≤5 mmol/L/h; insulin only once glucose stops falling on fluid alone (or at the outset if ketones ≥1 mmol/L), at 0.05 units/kg/h; prophylactic LMWH; sodium will rise as glucose falls (expected; a rise >10 mmol/L in 24 h is too fast). Foot checks daily."},{"name":"Hypoglycaemia","see":"In diabetes: <4 mmol/L (72 mg/dL) treat; ADA level 1 <3.9, level 2 <3.0 (54), level 3 any severe event needing help. Non-diabetic: Whipple's triad, glucose <3.0 mmol/L (55 mg/dL) with symptoms relieved by glucose","think":"Insulin and sulfonylureas (gliclazide hypoglycaemia recurs for 24–72 h and the patient must be admitted), alcohol with poor intake, renal failure prolonging insulin and sulfonylurea action, sepsis, liver failure, Addison's and hypopituitarism, insulinoma, non-islet cell tumours (IGF-2), post-bariatric surgery, factitious. Neuroglycopenia (confusion, focal deficit mimicking stroke, seizure) can occur without adrenergic warning in long-standing diabetes and on beta-blockers.","do":"Conscious: 15–20 g fast carbohydrate (glucose tablets, 150 mL juice), recheck at 10–15 min, repeat up to three times, then long-acting carbohydrate. Unconscious: 100 mL 20% glucose IV (or 1 mg glucagon IM if no access, less effective in alcohol or depleted glycogen). Give thiamine before glucose if malnourished or alcohol-dependent. Admit sulfonylurea and long-acting insulin hypoglycaemia. Non-diabetic unexplained hypoglycaemia: send the critical sample (glucose, insulin, C-peptide, proinsulin, β-hydroxybutyrate, cortisol, sulfonylurea screen) before correcting."},{"name":"Diagnosing diabetes","see":"HbA1c ≥48 mmol/mol (6.5%), fasting ≥7.0, 2 h OGTT ≥11.1 or random ≥11.1; one abnormal result with symptoms, or two on separate occasions if asymptomatic","think":"HbA1c cannot be used when red-cell turnover is abnormal, in pregnancy (use OGTT), in children and in suspected type 1 or symptoms of less than 2 months (use glucose; test ketones, consider antibodies and C-peptide). Type 1 is suggested by ketosis, weight loss, age <50, BMI <25, autoimmune history, but NICE NG17 advises against relying on age or BMI alone.","do":"Repeat the abnormal test if asymptomatic; HbA1c 42–47 is non-diabetic hyperglycaemia and the trigger for the NHS Diabetes Prevention Programme referral; screen for complications (ACR, retinal, feet, lipids, BP) at diagnosis of type 2."},{"name":"Stress hyperglycaemia","see":"Random glucose 8–15 mmol/L in an acutely ill patient with HbA1c <48 mmol/mol","think":"The HbA1c sent on the same sample separates undiagnosed diabetes (HbA1c ≥48) from stress hyperglycaemia; stress hyperglycaemia is a marker of illness severity (worse outcomes in MI, stroke and sepsis) and about a third of such patients develop diabetes within 5 years.","do":"Send HbA1c with any inpatient glucose >11.1; treat glucose >10–12 in the acutely ill with variable-rate insulin where local policy indicates; arrange a repeat HbA1c at 3 months after discharge."},{"name":"Euglycaemic DKA","see":"Ketones ≥3.0, pH <7.3 or bicarbonate <15, glucose <14 mmol/L (250 mg/dL), typically on an SGLT2 inhibitor, in pregnancy, after fasting or surgery, or with alcohol","think":"The normal-ish glucose delays the diagnosis; the patient is nauseated, hyperventilating and acidotic with a raised anion gap. Alcoholic ketoacidosis is the other classic: binge, then vomiting and no food, glucose low or normal, β-hydroxybutyrate high (urine dipstick may be weakly positive because the acetoacetate ratio is low).","do":"Treat as DKA with 10% glucose alongside the fixed-rate insulin from the start (ketones, not glucose, are the target); stop the SGLT2 inhibitor; for alcoholic ketoacidosis give glucose with thiamine and fluids (insulin not needed). Hold SGLT2 inhibitors for 3 days before surgery and during acute illness."}],"bedside":["Check a capillary glucose in every patient with altered consciousness, a seizure, a focal deficit, sweating or aggression before anything else; hypoglycaemia mimics stroke and intoxication and is reversed in minutes.","Kussmaul breathing with a ketotic (pear-drop) breath smell and dry mucous membranes in a vomiting young patient is DKA until the ketones say otherwise; about half of people cannot smell acetone.","Pallor, sweating, tremor and tachycardia are adrenergic warnings that are blunted by beta-blockers, autonomic neuropathy and long-standing diabetes; neuroglycopenic confusion may be the only sign.","Reduced skin turgor, dry axilla, postural hypotension and oliguria quantify the fluid deficit of HHS better than the glucose does; the patient with glucose 50 who looks dry needs litres, not just insulin."],"pitfalls":["Urine ketone dipsticks measure acetoacetate: they are negative or weak early in DKA and in alcoholic ketoacidosis (β-hydroxybutyrate dominant) and become more positive as DKA resolves and β-hydroxybutyrate converts back; use capillary blood ketones.","Sodium falls by about 2.4 mmol/L for every 5.6 mmol/L (100 mg/dL) of glucose above normal; a sodium of 128 with glucose 40 is a corrected sodium of about 143, and it will rise as glucose falls.","HbA1c is falsely low in haemolysis, recent transfusion, blood loss and late pregnancy, and falsely high in iron deficiency and CKD; a discordance between fingerprick readings and HbA1c should prompt a fructosamine or CGM review.","Capillary glucose meters read falsely high with icodextrin peritoneal dialysis fluid (maltose), and falsely low in shock with poor peripheral perfusion; confirm with a venous sample when the number and the patient disagree."],"src":["Joint British Diabetes Societies for Inpatient Care. The management of diabetic ketoacidosis in adults (revised 2023); The management of the hyperosmolar hyperglycaemic state in adults (2022); The hospital management of hypoglycaemia in adults with diabetes mellitus (2023)","Umpierrez GE et al. Hyperglycaemic crises in adults with diabetes: a consensus report (ADA/EASD/JBDS/AACE/DTS). Diabetologia and Diabetes Care 2024","American Diabetes Association. Standards of Care in Diabetes 2026 (Section 2: diagnosis and classification; Section 6: glycaemic goals and hypoglycaemia)","WHO. Use of glycated haemoglobin (HbA1c) in the diagnosis of diabetes mellitus (2011); NICE NG17 Type 1 diabetes in adults; NICE NG28 Type 2 diabetes in adults (updated 2022)","Cryer PE et al. Evaluation and management of adult hypoglycemic disorders: an Endocrine Society clinical practice guideline. J Clin Endocrinol Metab 2009"]},{"id":"thyroid","name":"Thyroid function","intro":"TSH is the single most useful test: the pituitary integrates thyroid hormone exposure and responds logarithmically, so a small change in free T4 produces a large change in TSH. The bedside question is whether the tremor, weight change, palpitations, fatigue or slow reflexes are thyroid, and the pattern of TSH against free T4 answers it, provided the patient is not acutely ill, pregnant or on a drug that distorts the axis.","items":[{"k":"TSH","n":"Thyroid-stimulating hormone","ref":"0.4–4.0 mIU/L (lab-dependent; upper limit rises with age, about 5–6 over 70; pregnancy trimester-specific, first trimester upper limit about 2.5–4.0)","meaning":"The screening test and the one to trust when the patient is stable; high means the thyroid is underperforming, suppressed means it is over-delivering, in primary disease.","high":"Primary hypothyroidism (autoimmune, post-ablative, amiodarone, lithium, iodine deficiency), recovery phase of non-thyroidal illness (transiently up to 20), poor adherence to levothyroxine (high TSH with normal or high fT4), TSH-secreting adenoma or thyroid hormone resistance (high with high fT4), adrenal insufficiency, assay interference (heterophile antibodies, biotin lowers it on some platforms).","low":"Hyperthyroidism (Graves', toxic nodule or goitre, thyroiditis, exogenous thyroxine), subclinical hyperthyroidism, non-thyroidal illness, glucocorticoids, dopamine, first-trimester hCG effect, central hypothyroidism (low or inappropriately normal with low fT4), over-replacement."},{"k":"fT4","n":"Free thyroxine","ref":"12–22 pmol/L (0.9–1.7 ng/dL)","meaning":"Confirms and grades what the TSH suggested; needed to separate subclinical from overt disease and to detect central disease.","high":"Hyperthyroidism, levothyroxine over-replacement or ingestion, amiodarone (raises fT4 even when euthyroid), heparin (in vitro, raises free fraction), biotin interference, familial dysalbuminaemic hyperthyroxinaemia, acute psychiatric illness.","low":"Hypothyroidism (primary with high TSH, central with low or normal TSH), severe non-thyroidal illness, phenytoin and carbamazepine (assay and binding effects), T3 therapy."},{"k":"fT3","n":"Free triiodothyronine","ref":"3.1–6.8 pmol/L (2.0–4.4 pg/mL)","meaning":"Add when TSH is suppressed with a normal fT4 (T3 toxicosis, 5% of hyperthyroidism) or to grade severity; it is the first to fall in illness and adds nothing in hypothyroidism.","high":"T3 toxicosis, early Graves', liothyronine, toxic nodule.","low":"Non-thyroidal illness (low T3 syndrome), starvation, amiodarone, beta-blockers, steroids, old age."},{"k":"TPO","n":"TPO antibodies, TRAb","ref":"TPO negative <35 IU/mL (lab-dependent); TRAb (TSH receptor antibody) positive confirms Graves'","meaning":"TPO positivity in subclinical hypothyroidism predicts progression to overt disease at about 4% per year; TRAb has a sensitivity and specificity above 95% for Graves' and avoids the uptake scan.","high":"Hashimoto's (TPO), Graves' (TRAb, also TPO in 70%), postpartum thyroiditis.","low":"Seronegative autoimmune disease exists (about 10%); negative TRAb with hyperthyroidism points to a nodule or thyroiditis (scan or ultrasound)."}],"patterns":[{"name":"Overt primary hypothyroidism","see":"TSH >10 mIU/L with fT4 below range (or TSH above range with low fT4)","think":"Autoimmune (Hashimoto's) in iodine-sufficient areas, post-radioiodine or surgery, amiodarone, lithium, immune checkpoint inhibitors, tyrosine kinase inhibitors. Myxoedema coma is the extreme: hypothermia, bradycardia, hyponatraemia, hypoglycaemia, reduced consciousness, usually precipitated by infection or sedatives in an elderly undiagnosed patient.","do":"Levothyroxine 1.6 µg/kg/day (25–50 µg starting dose if over 65 or ischaemic heart disease), recheck TSH at 6–8 weeks, titrate to TSH in range; NICE NG145. Check 9 am cortisol before starting if adrenal insufficiency possible (hyponatraemia, hypotension, pigmentation): thyroxine before hydrocortisone precipitates crisis. Myxoedema coma: ITU, IV levothyroxine or liothyronine, hydrocortisone, passive rewarming."},{"name":"Subclinical hypothyroidism","see":"TSH above range with normal fT4, confirmed on repeat at 3 months (up to 60% normalise spontaneously)","think":"Progression to overt disease about 2–4% per year, higher with TPO antibodies, TSH >10, and in women. Symptoms correlate poorly below TSH 10; most trials show no benefit of treatment for TSH <10 in older adults (TRUST trial).","do":"NICE NG145: TSH ≥10 on two occasions 3 months apart, treat. TSH 4–10 with symptoms and age under 65, consider a 6-month trial of levothyroxine and stop if no benefit; over 65, watch and wait. Treat lower thresholds in pregnancy or when trying to conceive (TSH target <2.5). Annual TSH if untreated with positive TPO, every 2–3 years if negative."},{"name":"Overt hyperthyroidism","see":"TSH suppressed (<0.1 mIU/L, often undetectable) with raised fT4 and/or fT3","think":"Graves' (diffuse goitre, bruit, eye disease, pretibial myxoedema, TRAb positive, younger women), toxic multinodular goitre or adenoma (older, nodular, no eye signs, scan hot), thyroiditis (painful subacute with raised ESR after a viral illness; painless postpartum or silent; amiodarone type 2; checkpoint inhibitors: hyperthyroid phase then hypothyroid, low uptake, no antithyroid drugs), exogenous (low thyroglobulin), hCG-driven (hyperemesis, molar pregnancy). Thyroid storm: fever, tachycardia >140, AF, agitation or coma, heart failure, with a precipitant (Burch-Wartofsky ≥45).","do":"TRAb (NICE NG145 first-line for cause), ultrasound if nodular or TRAb negative, uptake scan if still unclear; beta-blocker for symptoms, carbimazole (check FBC and LFTs first; counsel about agranulocytosis and sore throat) for Graves' and nodular disease, no antithyroid drugs for thyroiditis (NSAID, steroids if severe). Storm: propranolol, propylthiouracil or carbimazole, then iodine an hour later, hydrocortisone, cool, treat the precipitant."},{"name":"Subclinical hyperthyroidism","see":"TSH below range (especially <0.1) with normal fT4 and fT3, persistent on repeat at 3–6 months","think":"Toxic nodular disease in the elderly most often; also early Graves', over-replacement, and non-thyroidal illness or drugs (steroids, dopamine) which must be excluded by repeating when well. Risks: AF (threefold with TSH <0.1 in over-60s), osteoporosis, progression to overt disease about 1–5% per year.","do":"Repeat with fT3; if persistent and TSH <0.1, refer for cause and consider treatment particularly if over 65, AF, osteoporosis or cardiac disease (ETA 2015, NICE NG145). TSH 0.1–0.4: monitor 6-monthly unless symptomatic."},{"name":"Non-thyroidal illness (sick euthyroid)","see":"Any acutely or chronically ill inpatient: low fT3 first, then low or low-normal fT4 and TSH in severe illness; in recovery TSH rises transiently above range (up to 20 mIU/L) while fT4 normalises","think":"Adaptive reduction in T4 to T3 conversion and TSH drive; not a thyroid disease and not to be treated. The pattern mimics central hypothyroidism (low fT4, low TSH) and, in recovery, primary hypothyroidism. Dopamine, steroids, amiodarone and heparin add their own distortions.","do":"Do not request TFTs in acutely ill patients unless thyroid disease is suspected as the cause of the illness (new AF, myxoedema coma, storm); if sent and abnormal, repeat 6 weeks after recovery before diagnosing anything. A TSH >20 with low fT4 during illness is more likely true hypothyroidism."},{"name":"Discordant patterns","see":"TSH high with fT4 high; TSH low or normal with fT4 low; TSH normal with fT4 high","think":"TSH high, fT4 high: non-adherence to levothyroxine with a dose taken before the test (commonest), TSH-secreting pituitary adenoma, thyroid hormone resistance, assay interference (heterophile antibodies, biotin), amiodarone early. TSH low or inappropriately normal, fT4 low: central hypothyroidism (pituitary tumour, surgery, radiotherapy, Sheehan's, hypophysitis from checkpoint inhibitors; check cortisol, prolactin, gonadotrophins), non-thyroidal illness, recent treatment of hyperthyroidism (TSH suppression lags recovery by weeks to months). TSH normal, fT4 high: amiodarone, heparin (sample in vitro), biotin, familial dysalbuminaemic hyperthyroxinaemia, assay interference, T4 taken just before the sample.","do":"Repeat on a different assay platform, ask about biotin supplements (stop 48–72 h before), confirm adherence, and for suspected central disease measure 9 am cortisol and the other pituitary axes before thyroxine, then MRI pituitary."},{"name":"Amiodarone and the thyroid","see":"On amiodarone: fT4 often high-normal or mildly raised with normal TSH when euthyroid; TSH raised in amiodarone-induced hypothyroidism (14%); TSH suppressed with raised fT4 and fT3 in amiodarone-induced thyrotoxicosis (AIT, 3–6%, often with a sudden return of AF or weight loss)","think":"AIT type 1: underlying nodular or Graves' disease with iodine-driven overproduction (ultrasound shows vascularity; treat with carbimazole). Type 2: destructive thyroiditis in a normal gland (low vascularity; treat with prednisolone). Mixed cases are common.","do":"TFTs before starting amiodarone and every 6 months on it; do not stop amiodarone reflexively (long half-life, and the arrhythmia it controls); endocrinology discussion for AIT, often combined carbimazole and prednisolone when the type is unclear."}],"bedside":["Delayed relaxation of the ankle reflex (Woltman sign) LR+ about 3–4 for hypothyroidism; the combination of hoarse voice, dry cool skin, bradycardia and periorbital puffiness raises the pre-test probability but each alone is weak, which is why the TSH is sent.","Fine tremor of outstretched hands, resting tachycardia, warm moist palms, lid lag and a goitre with a bruit point to hyperthyroidism; lid retraction and stare occur in any thyrotoxicosis, but proptosis, chemosis and ophthalmoplegia are Graves' only.","New AF in an older patient: TSH is mandatory; subclinical hyperthyroidism from a nodule is a common and reversible cause.","Hypothermia, bradycardia, slow mentation and non-pitting oedema in an elderly woman with a thyroidectomy scar is myxoedema coma; the TSH confirms but treatment starts on clinical grounds."],"pitfalls":["Biotin (vitamin B7, common in hair and nail supplements at 5–10 mg) mimics Graves' on streptavidin-biotin immunoassays: suppressed TSH, raised fT4, raised TRAb; stop for 48–72 hours and repeat.","Thyroid tests in the acutely unwell are uninterpretable in most cases; do not start thyroxine on an inpatient TSH of 8 with a low fT3.","Levothyroxine takes 6–8 weeks to reach steady state; checking TSH earlier and adjusting the dose causes oscillation. Take the tablet after the blood test on the day of testing, or the fT4 will be falsely high.","Pregnancy needs trimester-specific ranges and the TSH target is lower (<2.5 in the first trimester); hCG suppresses TSH physiologically in hyperemesis and does not need antithyroid drugs."],"src":["NICE NG145 Thyroid disease: assessment and management (2019, updated 2023)","Ross DS et al. 2016 American Thyroid Association guidelines for diagnosis and management of hyperthyroidism and other causes of thyrotoxicosis. Thyroid 2016","Pearce SHS et al. 2013 ETA guideline: management of subclinical hypothyroidism; Biondi B et al. 2015 ETA guidelines on diagnosis and treatment of endogenous subclinical hyperthyroidism","Stott DJ et al. Thyroid hormone therapy for older adults with subclinical hypothyroidism (TRUST). NEJM 2017","Fliers E, Bianco AC, Langouche L, Boelen A. Thyroid function in critically ill patients. Lancet Diabetes Endocrinol 2015; Association for Clinical Biochemistry/BTA/BTF UK guidelines for the use of thyroid function tests (2006)"]},{"id":"calcium-bone","name":"Calcium, phosphate and bone","intro":"Calcium is a frequent incidental finding and an occasional emergency. The bedside question is whether the confusion, constipation, polyuria, bone pain or kidney stones are hypercalcaemia, and whether the tetany, perioral tingling or long QT is hypocalcaemia. The albumin-corrected calcium establishes the abnormality; the PTH taken at the same time establishes the cause in a single step.","items":[{"k":"Ca","n":"Adjusted (corrected) calcium","ref":"2.20–2.60 mmol/L (8.8–10.4 mg/dL). Adjusted calcium = measured + 0.02 × (40 − albumin g/L) in mmol/L (US: + 0.8 mg/dL per 1 g/dL albumin below 4). Ionised calcium 1.15–1.30 mmol/L on a gas","meaning":"Only the ionised 50% is active; albumin correction is a proxy that fails in acid–base disturbance, critical illness and paraproteinaemia, when ionised calcium on the gas should be used.","high":"Primary hyperparathyroidism (90% of ambulatory cases), malignancy (90% of inpatient cases: PTHrP from squamous lung, renal, breast; lytic metastases; myeloma; lymphoma via calcitriol), vitamin D excess, granulomatous disease (sarcoid, TB), thiazides, lithium, immobilisation, thyrotoxicosis, Addison's, milk-alkali, familial hypocalciuric hypercalcaemia, tertiary hyperparathyroidism.","low":"Vitamin D deficiency, CKD, hypoparathyroidism (post-thyroidectomy, autoimmune, DiGeorge), hypomagnesaemia, acute pancreatitis, rhabdomyolysis and tumour lysis (phosphate binds calcium), massive transfusion (citrate), bisphosphonates and denosumab, sepsis, pseudohypoparathyroidism."},{"k":"PTH","n":"Parathyroid hormone","ref":"1.6–6.9 pmol/L (15–65 pg/mL)","meaning":"Interpreted against the calcium: with hypercalcaemia any PTH in the upper half of the range or above is inappropriate and means parathyroid disease; with hypocalcaemia a PTH that is not raised means the parathyroids are failing.","high":"Primary hyperparathyroidism (with high Ca), secondary hyperparathyroidism (with low or normal Ca: vitamin D deficiency, CKD), tertiary (autonomous after long-standing secondary, high Ca), pseudohypoparathyroidism (high PTH, low Ca, resistance).","low":"Hypercalcaemia of malignancy and all non-parathyroid hypercalcaemia (suppressed, <2 pmol/L); hypoparathyroidism (with low Ca); hypomagnesaemia (impairs secretion)."},{"k":"PO4","n":"Phosphate","ref":"0.8–1.5 mmol/L (2.5–4.5 mg/dL)","meaning":"Moves opposite to PTH: low in hyperparathyroidism, high in hypoparathyroidism and CKD.","high":"CKD, hypoparathyroidism, rhabdomyolysis, tumour lysis, acidosis, vitamin D excess, haemolysed sample.","low":"Hyperparathyroidism, vitamin D deficiency, refeeding, alcohol, DKA treatment, respiratory alkalosis, phosphate binders, oncogenic osteomalacia."},{"k":"VitD","n":"25-hydroxyvitamin D","ref":"<25 nmol/L (10 ng/mL) deficient; 25–50 insufficient; >50 sufficient (NOS/SACN)","meaning":"The storage form; measure 25-OH, not 1,25-OH, unless granulomatous disease or lymphoma is suspected (1,25 raised).","high":"Supplement excess (toxicity usually >250 nmol/L).","low":"Low sunlight, dark skin, malabsorption, CKD, anticonvulsants, obesity."},{"k":"ALP-Ca","n":"Alkaline phosphatase with calcium","ref":"30–130 U/L","meaning":"High in bone disease with turnover (Paget's, metastases, osteomalacia, healing fracture, hyperparathyroidism); normal in myeloma (no osteoblast response) and in most primary hyperparathyroidism.","high":"Paget's, bone metastases, osteomalacia, hyperparathyroid bone disease, cholestasis.","low":"Hypophosphatasia."},{"k":"UCa","n":"Urine calcium:creatinine clearance ratio","ref":"<0.01 suggests familial hypocalcifuric hypercalcaemia; >0.02 primary hyperparathyroidism","meaning":"Separates FHH (benign, CASR mutation, no surgery) from primary hyperparathyroidism when PTH is inappropriately normal; also stones risk (24 h urine calcium >10 mmol).","high":"Primary hyperparathyroidism, vitamin D excess, sarcoid.","low":"FHH, thiazides, vitamin D deficiency."}],"patterns":[{"name":"Hypercalcaemia: the PTH decides","see":"Adjusted calcium >2.6 mmol/L confirmed on repeat, with a paired PTH","think":"PTH raised or in the upper half of normal: primary hyperparathyroidism (check urine calcium:creatinine ratio to exclude FHH, vitamin D, renal function, DXA, renal imaging for stones). PTH suppressed: malignancy (PTHrP, myeloma screen, CXR, CT), vitamin D toxicity, granulomatous disease (1,25-vitamin D, ACE, CXR), thyrotoxicosis, Addison's, drugs (thiazide, lithium, calcium and vitamin A supplements), immobilisation.","do":"NICE NG132: refer for parathyroidectomy if symptomatic, calcium ≥2.85 mmol/L, eGFR <60, stones, osteoporosis or fragility fracture, or age <50. NICE NG12: hypercalcaemia in a person aged 60 and over with features suggesting myeloma triggers FBC, calcium, ESR or plasma viscosity, then protein electrophoresis and light chains within 48 hours."},{"name":"Hypercalcaemia of malignancy","see":"Adjusted calcium >3.0 mmol/L (12 mg/dL), PTH suppressed, often with known cancer, dehydration, AKI, confusion, developing over days to weeks","think":"Humoral (PTHrP, 80%: squamous cell lung, head and neck, renal, bladder, breast, ovary), local osteolytic (breast, myeloma, lymphoma), calcitriol-mediated (Hodgkin and non-Hodgkin lymphoma, 1,25-D high). Median survival after this diagnosis is short (weeks to months); it is often a first presentation of the cancer.","do":"Calcium >3.0 or symptomatic: 0.9% saline 4–6 L in the first 24 h as tolerated (not loop diuretics unless fluid overloaded), then zoledronic acid 4 mg IV (maximal effect 2–4 days, lasts weeks; dose-adjust for eGFR <60), or denosumab if renal failure or bisphosphonate-refractory; calcitonin for 48 h if rapid lowering needed; steroids for lymphoma, myeloma, sarcoid, vitamin D toxicity. Stop calcium, vitamin D, thiazides and lithium; treat the cancer."},{"name":"Primary hyperparathyroidism","see":"Calcium mildly raised (2.6–2.85), PTH raised or inappropriately normal, phosphate low or low-normal, urine calcium raised or normal, 25-vitamin D often low, chloride:phosphate ratio >33","think":"Single adenoma in 85%, hyperplasia in 10–15% (MEN1, MEN2A in the young or with family history), carcinoma <1% (very high calcium and PTH, palpable mass). Most are asymptomatic in developed countries; stones, bones, abdominal groans and psychic moans is the older picture. Normocalcaemic primary hyperparathyroidism exists (PTH high, calcium normal, vitamin D replete).","do":"NICE NG132: measure calcium, PTH and vitamin D; sestamibi SPECT and ultrasound for localisation before surgery; DXA including distal radius; renal ultrasound; replace vitamin D cautiously. Medical management (cinacalcet) if surgery declined or unfit and calcium ≥2.85 or symptomatic."},{"name":"Hypocalcaemia: PTH high or low?","see":"Adjusted calcium <2.2 mmol/L, ionised <1.1; severe <1.9 or symptomatic (tetany, seizures, laryngospasm, QT prolongation, arrhythmia)","think":"PTH low or inappropriately normal: hypoparathyroidism (post-thyroid or parathyroid surgery within 24–72 h, autoimmune, radiation, infiltrative, genetic), hypomagnesaemia (<0.5 mmol/L blocks PTH release and action: alcohol, PPIs, diarrhoea, diuretics). PTH high: vitamin D deficiency (calcium low-normal, phosphate low, ALP high), CKD (phosphate high), pseudohypoparathyroidism (phosphate high, short fourth metacarpals), acute pancreatitis, rhabdomyolysis, tumour lysis, bisphosphonate or denosumab in vitamin D deficiency, hungry bone syndrome after parathyroidectomy, sepsis and critical illness.","do":"Severe or symptomatic: 10–20 mL 10% calcium gluconate IV over 10–20 min with ECG monitoring, then infusion (100 mL 10% in 1 L over 24 h titrated); replace magnesium first or calcium will not correct. Mild: oral calcium 1–2 g elemental daily and vitamin D; alfacalcidol or calcitriol in hypoparathyroidism and CKD. Post-thyroidectomy: check calcium at 6 and 24 h, PTH at 4 h predicts the need for supplements."},{"name":"Familial hypocalciuric hypercalcaemia","see":"Mild hypercalcaemia (2.6–2.9), PTH normal or mildly raised, urine calcium:creatinine clearance ratio <0.01, often lifelong and in relatives, magnesium high-normal","think":"Autosomal dominant inactivating mutation of the calcium-sensing receptor; benign, no stones or bone disease, parathyroidectomy does not cure it. Accounts for 1–2% of PTH-dependent hypercalcaemia and is the main reason surgery fails.","do":"Confirm with a 24 h urine (or spot ratio corrected for creatinine clearance), test relatives, CASR genetic testing; reassure and avoid surgery."},{"name":"Osteomalacia and vitamin D deficiency","see":"Low or low-normal calcium, low phosphate, raised ALP, raised PTH, 25-vitamin D <25 nmol/L; bone pain, proximal myopathy, waddling gait, Looser's zones on X-ray","think":"Dietary and sunlight deficiency (housebound, covered skin, dark skin at high latitude), malabsorption (coeliac, bariatric surgery, pancreatic insufficiency), anticonvulsants, CKD (reduced 1-alpha hydroxylation), hypophosphataemic rickets and oncogenic osteomalacia (FGF23, phosphate very low with normal vitamin D).","do":"Loading colecalciferol 300 000 IU over 6–10 weeks then maintenance 800–2000 IU daily (NOS 2018); check calcium 1 month after loading (unmasked primary hyperparathyroidism causes hypercalcaemia); coeliac serology; recheck ALP and PTH at 3 months, not the vitamin D level itself routinely."}],"bedside":["Trousseau's sign (carpal spasm within 3 minutes of a cuff inflated 20 mmHg above systolic) is present in about 94% of hypocalcaemic patients and 1% of normocalcaemic people; Chvostek's sign is present in about 10% of normal people and absent in a third of hypocalcaemic patients, so Trousseau's is the one to trust.","Hyperreflexia, perioral and acral paraesthesiae, carpopedal spasm and a prolonged QTc on the ECG go with hypocalcaemia; a shortened QT, bradycardia and a first-degree block go with hypercalcaemia.","Hypercalcaemia has no reliable bedside sign; polyuria and polydipsia with constipation, confusion, bone pain and dehydration in a patient with a smoking history or breast lump should trigger the test, and a band keratopathy at the limbus is a rare chronic marker.","A short fourth and fifth metacarpal (knuckle dimple on making a fist), short stature and round face with hypocalcaemia and a high PTH is pseudohypoparathyroidism (Albright's hereditary osteodystrophy)."],"pitfalls":["Albumin correction fails when the albumin is very low, in acidosis or alkalosis (alkalosis lowers ionised calcium and precipitates tetany at a normal total calcium, as in hyperventilation), in critical illness and with paraproteins; measure ionised calcium on the gas when it matters.","A single PTH without a simultaneous calcium cannot be interpreted; always pair them from the same draw, and remember that a PTH in the normal range with a calcium of 2.9 is primary hyperparathyroidism, not reassurance.","Tourniquet stasis and a sample after a calcium-containing meal or supplement raise the calcium by 0.1–0.2 mmol/L; repeat an unexpected mild hypercalcaemia fasting, without a tourniquet, before investigating.","Hypomagnesaemia makes hypocalcaemia and hypokalaemia resistant to replacement; measure magnesium in every hypocalcaemic patient and replace it first."],"src":["NICE NG132 Hyperparathyroidism (primary): diagnosis, assessment and initial management (2019)","Society for Endocrinology Emergency Guidance: acute hypercalcaemia (2016) and acute hypocalcaemia in adult patients (2016, Endocr Connect)","Bilezikian JP et al. Evaluation and management of primary hyperparathyroidism: summary statement and guidelines from the Fifth International Workshop. J Bone Miner Res 2022","National Osteoporosis Society (Royal Osteoporosis Society). Vitamin D and bone health: a practical clinical guideline for patient management (2018)","Cooper MS, Gittoes NJL. Diagnosis and management of hypocalcaemia. BMJ 2008; Minisola S et al. The diagnosis and management of hypercalcaemia. BMJ 2015; NICE NG12 (myeloma recognition)"]},{"id":"urinalysis","name":"Urinalysis","intro":"The dipstick is the cheapest test in the department and the most over-interpreted. It confirms or weakens a UTI story in a symptomatic younger woman, flags the glomerular disease behind an AKI, and finds the protein that predicts cardiovascular and renal risk. In older adults and catheterised patients it mostly measures asymptomatic bacteriuria and should usually not be done.","items":[{"k":"Nit","n":"Nitrite","ref":"Negative","meaning":"Gram-negative bacteria convert dietary nitrate to nitrite over about 4 hours in the bladder; a positive is fairly specific for bacteriuria (specificity 90–98%, sensitivity 45–60%); LR+ about 5–10, LR− about 0.5.","high":"E. coli, Klebsiella, Proteus and other Enterobacterales; false positive with a sample left standing or contamination.","low":"Enterococcus, Staphylococcus saprophyticus, Pseudomonas and other non-nitrate reducers; frequent voiding (<4 h in bladder); low dietary nitrate; vitamin C (false negative)."},{"k":"LE","n":"Leucocyte esterase","ref":"Negative","meaning":"Marks pyuria (neutrophils); sensitive (75–90%) but not specific (LR+ about 1.5–2.5, LR− about 0.2–0.3); pyuria without bacteriuria is sterile pyuria.","high":"UTI, urethritis (chlamydia, gonorrhoea), vaginal contamination, renal stones, interstitial nephritis, TB, appendicitis adjacent to the ureter, recent antibiotics, bladder tumour.","low":"Not helpful alone; false negative with glycosuria, high specific gravity, vitamin C, some antibiotics (cephalexin, nitrofurantoin)."},{"k":"Blood","n":"Blood (haem)","ref":"Negative; 1+ or more is positive (trace is generally not actionable; NICE NG12 uses 1+ for non-visible haematuria)","meaning":"Detects intact red cells, free haemoglobin and myoglobin alike; microscopy (≥3 RBC per high-power field) distinguishes. Dysmorphic red cells and red cell casts mean glomerular bleeding.","high":"UTI, stones, bladder or renal cancer, glomerulonephritis, IgA nephropathy, BPH, exercise, menstruation, trauma, catheter; haemoglobinuria (haemolysis) and myoglobinuria (rhabdomyolysis) with no red cells on microscopy.","low":"Vitamin C causes false negatives; high specific gravity reduces sensitivity."},{"k":"Prot","n":"Protein","ref":"Negative or trace; the dipstick detects albumin at about 300 mg/L and above and misses microalbuminuria. Quantify with ACR: normal <3 mg/mmol, A2 3–30, A3 >30; PCR >100 mg/mmol about 1 g/day; nephrotic ACR >220 or PCR >300 mg/mmol (3.5 g/day)","meaning":"Albuminuria is the earliest sign of diabetic and hypertensive kidney disease and an independent cardiovascular risk marker; the ACR, not the dipstick, is the test (NICE NG203).","high":"Glomerular disease, diabetic nephropathy, hypertension, pre-eclampsia (ACR ≥8 or PCR ≥30 mg/mmol), UTI, fever, exercise, orthostatic proteinuria in the young, heart failure, myeloma (dipstick negative for light chains; use urine protein electrophoresis).","low":"Dilute urine lowers sensitivity; alkaline urine (pH >8) and chlorhexidine give false positives."},{"k":"Gluc","n":"Glucose","ref":"Negative","meaning":"Appears when plasma glucose exceeds the renal threshold (about 10 mmol/L) or the threshold is lowered.","high":"Diabetes, SGLT2 inhibitors (expected, not a sign of poor control), pregnancy, renal glycosuria, Fanconi syndrome, steroids.","low":"Not applicable."},{"k":"Ket","n":"Ketones (acetoacetate)","ref":"Negative","meaning":"Fasting, vomiting and DKA; the stick misses β-hydroxybutyrate so it under-reads early DKA and alcoholic ketoacidosis; use blood ketones for diagnosis and monitoring.","high":"Starvation, vomiting (hyperemesis), DKA, alcoholic ketoacidosis, ketogenic diets, prolonged exercise; false positives with captopril, levodopa, mesna.","low":"Not applicable."},{"k":"SG-pH","n":"Specific gravity and pH","ref":"SG 1.003–1.030; pH 4.5–8","meaning":"SG above 1.020 means concentrated urine (prerenal state); below 1.005 means dilute (diabetes insipidus, polydipsia, diuretics); pH >7 with UTI suggests urease producers (Proteus) and struvite stones; persistent pH >5.5 in metabolic acidosis suggests distal RTA.","high":"SG: dehydration, glycosuria, contrast; pH: Proteus, RTA, vegetarian diet, alkali therapy.","low":"SG: DI, overhydration, CKD (fixed 1.010); pH: acidosis, high protein diet, uric acid stones."},{"k":"Bili-Uro","n":"Bilirubin and urobilinogen","ref":"Bilirubin negative; urobilinogen trace","meaning":"Urine bilirubin is conjugated bilirubin, so it appears in hepatocellular and obstructive jaundice but not haemolysis; urobilinogen rises in haemolysis and hepatocellular disease and disappears in complete biliary obstruction.","high":"Bilirubin: cholestasis, hepatitis; urobilinogen: haemolysis, hepatitis, constipation.","low":"Absent urobilinogen with bilirubin positive: complete obstruction or antibiotics suppressing gut flora."}],"patterns":[{"name":"UTI in women under 65 (non-pregnant)","see":"Dysuria, frequency, urgency, suprapubic pain, visible haematuria, nocturia; UKHSA/NICE NG109 diagnostic flowchart","think":"Two or more key symptoms (dysuria, new nocturia, cloudy urine) with no vaginal discharge: UTI probable (likelihood >80%), treat empirically without a dipstick. One symptom or an unclear picture: dipstick; nitrite or leucocytes positive with blood raises the probability (nitrite positive alone LR+ about 5–10); all three negative makes UTI unlikely (LR− about 0.2–0.3) and suggests urethritis, vaginitis or interstitial cystitis. Pyelonephritis: fever, loin pain, rigors, vomiting; culture before antibiotics.","do":"Uncomplicated cystitis: nitrofurantoin 3 days (if eGFR ≥45) or trimethoprim if local resistance low; culture only if recurrent, treatment failure, pregnancy, pyelonephritis or atypical. Back-up prescription for mild symptoms. Dysuria with discharge or sexual risk: test for chlamydia and gonorrhoea."},{"name":"UTI in men","see":"Urinary symptoms in a man; UTI less common and more often complicated (prostatitis, obstruction, stones, catheter)","think":"Nitrite positive is useful (specificity high); a negative dipstick does not exclude it as well as in women. Always send a culture before antibiotics. Perineal or low back pain, fever, tender prostate on PR suggests prostatitis (14-day course). Recurrent UTI or any first UTI in a man under 50 warrants looking for a cause.","do":"7-day course (nitrofurantoin or trimethoprim for cystitis; ciprofloxacin or trimethoprim 14 days for prostatitis); urology referral for recurrence, haematuria persisting after treatment, obstructive symptoms or stones; PSA is unreliable for 6 weeks after infection."},{"name":"Urinary symptoms and confusion in people over 65","see":"Older adult, delirium or fall, carers reporting cloudy or smelly urine; dipstick requested","think":"Asymptomatic bacteriuria is present in 25–50% of women and 15–40% of men in care homes, and in 100% of long-term catheterised patients, so a positive dipstick (nitrite, leucocytes) has no diagnostic value and a negative one has some. Delirium alone is not a UTI symptom; treating bacteriuria for confusion exposes the patient to antibiotic harms and misses the real cause (dehydration, drugs, constipation, pneumonia, pain). UKHSA/NICE: do not dipstick over-65s or catheterised patients.","do":"Diagnose UTI in over-65s on new urinary symptoms (dysuria, frequency, suprapubic pain, visible haematuria, new incontinence), fever or rigors, loin pain, with a culture sent; look for other causes of delirium (full examination, bloods, chest X-ray, medication review). In catheterised patients, change the catheter, send culture from the new catheter, and treat only with systemic signs."},{"name":"Haematuria","see":"Visible haematuria, or non-visible (1+ or more on dipstick, confirmed on 2 of 3 samples a week apart, with UTI excluded)","think":"NICE NG12 suspected cancer pathway (2-week wait urology): aged 45 and over with unexplained visible haematuria without UTI, or visible haematuria that persists or recurs after successful UTI treatment; aged 60 and over with unexplained non-visible haematuria and either dysuria or a raised white cell count. Persistent non-visible haematuria under 60 or without those features: check ACR, eGFR and blood pressure; glomerular causes (IgA nephropathy, thin basement membrane) if proteinuria, dysmorphic cells or casts, or raised creatinine. Transient haematuria: UTI, exercise, menstruation, instrumentation. Dipstick positive with no red cells on microscopy: myoglobin (rhabdomyolysis, CK) or haemoglobin (haemolysis).","do":"Exclude UTI and repeat; urgent urology (cystoscopy and upper tract imaging) per NG12 criteria, non-urgent urology for persistent non-visible haematuria over 40 or with risk factors (smoking, occupational dye exposure); nephrology if proteinuria (ACR ≥30, or ≥70 alone), eGFR falling, hypertension or under 40 with glomerular features. Anticoagulation does not explain haematuria: investigate the same way."},{"name":"Proteinuria","see":"Dipstick protein 1+ or more, or ACR ≥3 mg/mmol on an early morning sample","think":"Dipstick 1+ corresponds roughly to 300 mg/L; confirm and quantify with ACR (PCR if ACR ≥70). Transient: fever, exercise, UTI, heart failure, orthostatic (young, absent in first morning sample). Persistent: diabetic nephropathy (microalbuminuria A2 is the earliest stage), hypertension, glomerulonephritis (with haematuria), nephrotic syndrome (oedema, albumin <30, ACR >220), myeloma (dipstick negative, Bence Jones protein on electrophoresis). Pregnancy over 20 weeks with hypertension: pre-eclampsia (PCR ≥30 or ACR ≥8 mg/mmol; placental growth factor testing per NICE NG133).","do":"NICE NG203: ACR ≥3 persisting defines CKD regardless of eGFR; ACR 3–70 repeat on an early morning sample within 3 months; refer nephrology for ACR ≥70 (unless diabetic and treated), ACR ≥30 with haematuria, or nephrotic range; start ACE inhibitor or ARB and SGLT2 inhibitor for albuminuric CKD; dipstick-negative proteinuria with bone pain, anaemia or hypercalcaemia goes to protein electrophoresis."},{"name":"Sterile pyuria","see":"Leucocytes positive, nitrite negative, culture no growth","think":"Recently treated UTI (commonest), chlamydia or gonorrhoea urethritis, genital tract contamination, renal or ureteric stones, interstitial nephritis (drugs: PPIs, NSAIDs, antibiotics; with eosinophilia, rash, AKI), renal TB (classic, three early morning urines), bladder tumour, appendicitis or diverticulitis adjacent to the bladder, Kawasaki in children, fastidious organisms.","do":"Sexual health screen, repeat clean-catch culture off antibiotics, imaging for stones if pain, urine cytology and cystoscopy if haematuria or risk factors, TB cultures if persistent and from an endemic area or immunosuppressed."},{"name":"Active urinary sediment in AKI","see":"AKI with dipstick blood and protein, red cell casts or dysmorphic cells on microscopy, often with hypertension and oedema","think":"Glomerulonephritis or vasculitis (ANCA-associated, anti-GBM, lupus, post-infectious, IgA): a renal emergency where days matter. Bland dipstick with AKI points to prerenal, obstructive or ATN causes; white cell casts and eosinophils suggest interstitial nephritis; muddy brown granular casts suggest ATN; heavy haem positivity without red cells suggests rhabdomyolysis.","do":"Same-day nephrology discussion for a nephritic picture: ANCA, anti-GBM, ANA, complement, immunoglobulins, hepatitis B and C, HIV, ASOT, blood cultures, urine PCR, renal ultrasound, early biopsy; stop nephrotoxins; CK for rhabdomyolysis."}],"bedside":["Suprapubic tenderness and costovertebral angle tenderness have poor sensitivity for UTI but loin tenderness with fever shifts the diagnosis to pyelonephritis and the need for culture, bloods and imaging if not settling in 48 hours.","Vaginal discharge or irritation with dysuria halves the probability of UTI (LR− about 0.3–0.7) and points to vaginitis or urethritis; ask before dipping.","Periorbital oedema, frothy urine and pitting oedema with a dipstick showing 3+ or 4+ protein is nephrotic syndrome; hypertension, haematuria and oedema with blood and protein is nephritic.","Blood on the stick, tea-coloured urine and muscle tenderness after a fall with a long lie, exertion, seizure or statin use is rhabdomyolysis until the CK and urine microscopy (no red cells) confirm it."],"pitfalls":["Dipstick urinalysis in asymptomatic older adults, catheterised patients and pre-operative screening generates false UTI diagnoses and antibiotic harm; the test is not indicated and a positive result should not be treated.","Nitrite needs about 4 hours of bladder dwell time and a nitrate-reducing organism; a frequent voider with enterococcal or staphylococcal infection will be nitrite negative. Leucocyte esterase is lost in glycosuria and concentrated urine.","Protein dipstick misses microalbuminuria and light chains; a negative dipstick does not exclude diabetic nephropathy (send ACR) or myeloma (send electrophoresis).","Samples left over 2 hours at room temperature grow bacteria (false nitrite positive), lyse cells (false leucocyte negative) and alkalinise; refrigerate or send promptly, and label the collection method (clean catch, catheter, bag)."],"src":["UK Health Security Agency. Diagnosis of urinary tract infections: quick reference tool for primary care (updated 2024); NICE NG109 Urinary tract infection (lower): antimicrobial prescribing (2018); NICE NG111 Pyelonephritis (acute)","SIGN 160 Management of suspected bacterial lower urinary tract infection in adult women (2020)","NICE NG12 Suspected cancer: recognition and referral (haematuria criteria); NICE NG203 Chronic kidney disease (ACR thresholds and referral)","Simerville JA, Maxted WC, Pahira JJ. Urinalysis: a comprehensive review. Am Fam Physician 2005; Devillé WLJM et al. The urine dipstick test useful to rule out infections: a meta-analysis of the accuracy. BMC Urol 2004","Nicolle LE et al. IDSA clinical practice guideline for the management of asymptomatic bacteriuria (2019); Medina-Bombardó D, Jover-Palmer A. Does clinical examination aid in the diagnosis of urinary tract infections in women? BMC Fam Pract 2011"]},{"id":"coagulation","name":"Coagulation","intro":"The coagulation screen answers whether a bleeding or bruising patient has a clotting factor problem, which arm of the cascade it lies in, and whether an anticoagulant is responsible. It does not test platelets, von Willebrand factor or vessel wall, which cause most bleeding you see, so a normal screen with a convincing bleeding history still needs explaining.","items":[{"k":"PT","n":"Prothrombin time / INR","ref":"PT 11–14 s; INR 0.8–1.2 (INR is standardised for warfarin monitoring only; use the PT in seconds for liver disease and DIC in principle, though the INR is reported)","meaning":"Extrinsic and common pathways: factors VII, X, V, II and fibrinogen; factor VII has the shortest half-life, so the PT moves first in liver disease, vitamin K deficiency and warfarin.","high":"Warfarin, vitamin K deficiency (malabsorption, prolonged antibiotics, cholestasis, poor intake), liver disease, DIC, factor VII deficiency, massive transfusion, rivaroxaban and edoxaban (variable, assay-dependent), high-dose heparin.","low":"Not clinically relevant."},{"k":"APTT","n":"Activated partial thromboplastin time","ref":"25–35 s (lab-dependent); APTT ratio 0.8–1.2; therapeutic unfractionated heparin ratio 1.5–2.5","meaning":"Intrinsic and common pathways: XII, XI, IX, VIII, X, V, II, fibrinogen; prolonged by factor deficiency, inhibitors and heparin.","high":"Unfractionated heparin (and LMWH slightly), dabigatran, haemophilia A (VIII) or B (IX), von Willebrand disease (if VIII low), factor XI deficiency, factor XII deficiency (no bleeding), lupus anticoagulant (no bleeding, thrombosis), acquired haemophilia (anti-VIII inhibitor in the elderly with new bruising), DIC, liver disease, sample contamination from a heparinised line.","low":"Acute-phase response (high VIII, fibrinogen), underfilled tube artefact; not clinically relevant."},{"k":"Fib","n":"Fibrinogen","ref":"1.5–4.0 g/L (150–400 mg/dL)","meaning":"The final substrate; an acute-phase reactant that rises in inflammation, so a normal fibrinogen in a septic patient may already represent consumption.","high":"Inflammation, infection, pregnancy, malignancy, smoking.","low":"DIC, massive haemorrhage and dilution, liver failure, thrombolysis, L-asparaginase, congenital hypofibrinogenaemia; <1.5 g/L in major haemorrhage or <2 in obstetric haemorrhage is the trigger for cryoprecipitate or fibrinogen concentrate."},{"k":"TT","n":"Thrombin time","ref":"12–16 s (lab-dependent)","meaning":"Fibrinogen to fibrin conversion; very sensitive to heparin and dabigatran, so a normal TT excludes a clinically relevant dabigatran level.","high":"Heparin contamination, dabigatran, low or dysfunctional fibrinogen, high fibrin degradation products (DIC), paraproteins.","low":"Not relevant."},{"k":"aXa","n":"Anti-Xa level","ref":"Drug-calibrated: LMWH treatment peak 0.6–1.0 IU/mL at 4 h (once daily 1.0–2.0); rivaroxaban and apixaban levels reported in ng/mL against drug calibrators","meaning":"The only reliable measure of LMWH, rivaroxaban, apixaban and edoxaban effect; the PT and APTT are insensitive to apixaban in particular.","high":"Accumulation in renal failure, overdose, extremes of weight.","low":"Non-adherence, under-dosing in obesity."},{"k":"Mix","n":"Mixing study (50:50 with normal plasma)","ref":"Corrects (to within a few seconds of normal) or fails to correct","meaning":"A prolonged APTT that corrects on mixing indicates factor deficiency; failure to correct, especially after incubation, indicates an inhibitor (lupus anticoagulant or a specific factor inhibitor).","high":"Not applicable.","low":"Not applicable."}],"patterns":[{"name":"Isolated prolonged PT","see":"PT or INR raised, APTT normal, fibrinogen and platelets normal","think":"Early warfarin or vitamin K deficiency (factor VII falls first), early or mild liver disease, isolated factor VII deficiency (rare), rivaroxaban or edoxaban, early DIC. Vitamin K deficiency is common in the sick inpatient on antibiotics with poor intake, and in cholestasis.","do":"Drug history, LFTs, give vitamin K 10 mg IV if deficiency possible and recheck at 24 h (correction confirms deficiency; failure suggests liver synthetic failure). Warfarin management per BSH: INR 5–8 without bleeding, omit doses; INR >8 without bleeding, oral vitamin K 1–5 mg; major bleeding at any INR, stop warfarin, IV vitamin K 5–10 mg and four-factor prothrombin complex concentrate 25–50 units/kg."},{"name":"Isolated prolonged APTT","see":"APTT raised, PT normal","think":"Bleeding history: haemophilia A or B (lifelong, male, joint and muscle bleeds; factor VIII or IX assay), von Willebrand disease (mucosal bleeding, menorrhagia; VWF antigen and activity, VIII; APTT often normal in mild disease), factor XI deficiency (Ashkenazi), acquired haemophilia (new severe bruising in the elderly or postpartum, anti-VIII inhibitor, haematology emergency). No bleeding history: lupus anticoagulant (associated with thrombosis and miscarriage, not bleeding), factor XII deficiency, heparin contamination from a line, dabigatran.","do":"Repeat from a clean peripheral stab, thrombin time (prolonged with heparin or dabigatran, normal with factor deficiency), mixing study, then factor assays or lupus anticoagulant testing as directed. Never give FFP for a prolonged APTT without a bleeding history or a diagnosis."},{"name":"Both PT and APTT prolonged","see":"PT and APTT raised; platelets and fibrinogen decide the rest","think":"Common pathway or multiple factor problem: DIC (platelets and fibrinogen low, D-dimer very high), liver failure (fibrinogen low late, platelets low from hypersplenism, factor VIII normal or high, which distinguishes it from DIC), severe vitamin K deficiency or warfarin overdose, massive transfusion dilution, supratherapeutic heparin, dabigatran, rare factor X, V, II or fibrinogen deficiency, amyloid (factor X).","do":"Fibrinogen, platelets, D-dimer, LFTs, drug history; vitamin K trial; treat the cause; replace only if bleeding or before a procedure (FFP 15 mL/kg, cryoprecipitate for fibrinogen <1.5, platelets if <50 and bleeding)."},{"name":"Disseminated intravascular coagulation","see":"ISTH overt DIC score ≥5: platelets (<100 = 1, <50 = 2), D-dimer or fibrin markers (moderate rise = 2, strong rise = 3), PT prolongation (3–6 s = 1, >6 s = 2), fibrinogen <1 g/L = 1; in a patient with a predisposing condition","think":"Sepsis (commonest), trauma and burns, obstetric catastrophe (abruption, amniotic fluid embolism, retained dead fetus, pre-eclampsia), malignancy (acute promyelocytic leukaemia, adenocarcinoma: chronic DIC with thrombosis), snake bite, transfusion reaction, aortic aneurysm, liver failure. Bleeding from venepuncture sites and lines, purpura fulminans and microvascular thrombosis with organ failure are the picture.","do":"Treat the cause above all. Transfuse only if bleeding or high risk: platelets to >50, FFP for PT or APTT ratio >1.5, cryoprecipitate for fibrinogen <1.5; LMWH prophylaxis in non-bleeding patients; tranexamic acid is contraindicated except in some trauma and APL settings; APL with DIC needs ATRA urgently. Score daily; haematology involvement."},{"name":"Anticoagulant effects on the screen","see":"Patient on a known or suspected anticoagulant presenting with bleeding, trauma, or needing surgery","think":"Warfarin: INR, reliable. Unfractionated heparin: APTT ratio (anti-Xa if APTT unreliable, as with lupus anticoagulant or high factor VIII). LMWH: APTT barely moves; anti-Xa only. Dabigatran: APTT prolonged (insensitive at low levels), TT very sensitive (normal TT excludes meaningful drug), dilute TT or ecarin time quantify. Rivaroxaban and edoxaban: PT prolonged variably (a normal PT with a sensitive reagent makes a high level unlikely but does not exclude it); anti-Xa calibrated. Apixaban: PT and APTT often normal at therapeutic levels; anti-Xa only.","do":"Record the drug, dose and time of last dose; check creatinine (DOAC accumulation). Life-threatening bleeding: idarucizumab for dabigatran, andexanet alfa (where available) or four-factor PCC 25–50 units/kg for factor Xa inhibitors, PCC plus vitamin K for warfarin; tranexamic acid; haematology input. Hold DOACs before surgery by 24–48 h (longer with renal impairment, dabigatran and high-bleeding-risk procedures)."},{"name":"Normal screen with a bleeding history","see":"PT, APTT, fibrinogen and platelet count normal; recurrent epistaxis, menorrhagia, easy bruising, prolonged bleeding after extractions or surgery","think":"Von Willebrand disease (commonest inherited bleeding disorder, 1%; APTT normal in most type 1), platelet function disorders (aspirin, clopidogrel, NSAIDs, uraemia, inherited), mild factor deficiencies, factor XIII deficiency (normal screen, delayed bleeding, poor wound healing), vascular causes (Ehlers-Danlos, scurvy, senile purpura, steroid skin), and non-accidental injury. A structured bleeding assessment tool (ISTH-BAT) score ≥4 in men or ≥6 in women is abnormal.","do":"Drug review, VWF antigen and activity, factor VIII, platelet function testing (PFA-100 as a screen, then aggregometry), factor XIII, blood film; haematology referral if the bleeding history is convincing regardless of the results. Normal results do not exclude a bleeding disorder before surgery if the history is strong."},{"name":"Heparin-induced thrombocytopenia","see":"Platelet fall >50% (or new thrombosis) 5–10 days after starting heparin (or within 24 h if exposed in the previous 100 days), nadir rarely below 20, no other cause; 4Ts score ≥4","think":"Immune (anti-PF4/heparin) prothrombotic state despite thrombocytopenia; venous and arterial thrombosis in 30–50% if untreated, skin necrosis at injection sites. Commoner with unfractionated than LMWH, and after cardiac and orthopaedic surgery.","do":"Stop all heparin (including flushes and coated lines), start a non-heparin anticoagulant (argatroban, fondaparinux, or a DOAC per haematology), send anti-PF4 antibodies and confirm with a functional assay, do not transfuse platelets prophylactically, no warfarin until platelets recover (skin necrosis risk)."}],"bedside":["Petechiae, mucosal bleeding and bruising of the skin suggest a platelet or vessel problem; haemarthroses, deep muscle haematomas and delayed bleeding after surgery suggest a factor deficiency. The screen only addresses the second group.","Oozing from venepuncture sites, cannulae and wounds in a septic or obstetric patient is DIC until the fibrinogen and platelets say otherwise; it precedes the laboratory picture.","Signs of chronic liver disease with bruising mean that the INR reflects reduced synthesis of both procoagulant and anticoagulant factors; these patients are not auto-anticoagulated and can thrombose, and FFP does not reliably correct the INR.","Joint hypermobility, skin hyperextensibility and atrophic scars with easy bruising point to a connective tissue (vascular) cause with a normal coagulation screen."],"pitfalls":["Underfilled citrate tubes, samples drawn through heparinised lines, high haematocrit (>55%) and delayed processing all prolong the PT and APTT spuriously; repeat with a correctly filled peripheral sample before investigating.","Normal PT and APTT do not exclude a bleeding disorder: von Willebrand disease, platelet dysfunction, factor XIII deficiency and mild haemophilia all hide behind a normal screen.","The INR is validated for warfarin only; in liver disease it does not predict bleeding risk, and a raised INR does not protect against thrombosis or justify withholding VTE prophylaxis.","A normal APTT and PT do not exclude therapeutic apixaban or rivaroxaban; ask about the drug and the last dose, and use anti-Xa if the answer matters."],"src":["Keeling D et al. Guidelines on oral anticoagulation with warfarin, 4th edition. BSH, Br J Haematol 2011; Makris M et al. BSH guideline on the management of bleeding in patients on antithrombotic agents (2013)","Levi M et al. Guidelines for the diagnosis and management of disseminated intravascular coagulation. BSH, Br J Haematol 2009; Taylor FB et al. ISTH scientific standardisation committee DIC scoring system. Thromb Haemost 2001","Watson HG et al. BSH guideline on the management of heparin-induced thrombocytopenia (2012); Cuker A et al. ASH 2018 guidelines for management of VTE: heparin-induced thrombocytopenia. Blood Adv 2018","Laffan MA et al. BSH guideline: the diagnosis and management of von Willebrand disease (2014); Rodeghiero F et al. ISTH/SSC bleeding assessment tool (ISTH-BAT). J Thromb Haemost 2010","Douxfils J et al. 2021 Update of the International Council for Standardization in Haematology recommendations for laboratory measurement of direct oral anticoagulants. Thromb Haemost 2021; Stanworth SJ et al. Haematological management of major haemorrhage: a BSH guideline (2022)"]}];
